import type {MouseEvent} from 'react'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {CopilotChatReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {OutputDisplay} from './shared/OutputDisplay'
import type {NodeValue} from '../types/app'
import {AppContextProvider} from '../contexts/AppContextProvider'
import {LinkButton} from '@primer/react'
import {PencilIcon} from '@primer/octicons-react'
import {useNavigate} from '@github-ui/use-navigate'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {referenceURL} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {generateDefaultModel} from '@github-ui/copilot-chat/utils/models'
import styles from './LoopExecutionPreview.module.css'

export function withPreviewURL(previewURL: string) {
  return function LoopExecutionPreview({reference}: {reference: CopilotChatReference}) {
    const navigate = useNavigate()
    const manager = useChatManager()

    if (reference.type !== 'loop-execution') return null

    const editLoopURL = referenceURL(reference)
    const editLoop = async (e: MouseEvent) => {
      e.preventDefault()
      await manager.selectThread(null)
      navigate(editLoopURL)
    }

    return (
      <AppContextProvider
        previewUrl={previewURL}
        availableModels={[]}
        defaultModel={generateDefaultModel()}
        sendChatMessage={() => {}}
      >
        <div className={styles.previewContainer}>
          <div className={styles.buttonContainer}>
            <LinkButton href={editLoopURL} leadingVisual={PencilIcon} onClick={editLoop}>
              Edit this loop
            </LinkButton>
          </div>

          <div className={styles.contentContainer}>
            <OutputDisplay isRunning={false} nodeValue={reference.output[0]?.value as NodeValue} />
          </div>
        </div>
      </AppContextProvider>
    )
  }
}

try{ LoopExecutionPreview.displayName ||= 'LoopExecutionPreview' } catch {}