import type {Node} from '../types/app'
import type {ChatCompletionsClient} from './chat-completions-client'
import type {GraphQLClient} from './graphql-client'
import {nodeHandlerRegistry} from './node-handler-registry'
import type {NodeExecutionContext, NodeExecutionResult} from '../types/node-handler-interface'
import type {Execution} from '../types/execution'
import type {CodeExecutor} from './code-executor'

export class NodeRunner {
  readonly #node: Node
  readonly #graphQLClient: GraphQLClient
  readonly #chatClient: ChatCompletionsClient
  readonly #codeExecutor: CodeExecutor

  constructor(node: Node, gqlClient: GraphQLClient, chatClient: ChatCompletionsClient, codeExecutor: CodeExecutor) {
    this.#node = node
    this.#graphQLClient = gqlClient
    this.#chatClient = chatClient
    this.#codeExecutor = codeExecutor
  }

  async run(
    execution: Execution,
    signal?: AbortSignal,
    onPartialResult?: (result: string) => void,
  ): Promise<NodeExecutionResult> {
    const context: NodeExecutionContext = {
      graphQLClient: this.#graphQLClient,
      chatClient: this.#chatClient,
      codeExecutor: this.#codeExecutor,
      signal,
      onPartialResult,
      execution,
    }

    return nodeHandlerRegistry.executeNode(this.#node, context)
  }
}
