import type {ReactNode} from 'react'

interface SubtasksGroupProps {
  children: ReactNode
  isStreaming: boolean
  taskCount: number
}

export function SubtasksGroup({children, isStreaming, taskCount}: SubtasksGroupProps) {
  if (!isStreaming && taskCount === 0) {
    return <span>No tasks were created, please retry.</span>
  }

  return <>{children}</>
}

try{ SubtasksGroup.displayName ||= 'SubtasksGroup' } catch {}