import {ContentView} from '@github-ui/pacer/ContentView'
import {Blankslate} from '@primer/react/experimental'
import {AgentIcon} from '@primer/octicons-react'
import styles from './AgentsBlankslate.module.css'
import type {MemberRequestEntities} from '../../types/agent-tasks-app-payload'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {AccessDisabledBanner, AccessRequestBanner, UpgradeBanner} from './AgentsBlankslateBanner'

export interface AgentsBlankslateProps {
  hasCEorCBAccess?: boolean
  memberRequestEntities?: MemberRequestEntities
}

export function AgentsBlankslate({hasCEorCBAccess, memberRequestEntities}: AgentsBlankslateProps) {
  const memberRequestsEnabled = isFeatureEnabled('copilot_agents_blankslate_mem_requests')
  const requestableOrgs = memberRequestEntities?.orgs?.requestable || []
  const adminableOrgs = memberRequestEntities?.orgs?.adminable || []
  const hasOrgs = requestableOrgs.length + adminableOrgs.length > 0
  const showMemberRequests =
    memberRequestsEnabled && memberRequestEntities && (hasOrgs || memberRequestEntities.enterprise)

  return (
    <>
      <ContentView.Container width="large">
        <Blankslate size="medium" className={styles.blankslate}>
          <Blankslate.Visual>
            <AgentIcon size={24} />
          </Blankslate.Visual>
          <Blankslate.Heading>Delegate tasks to GitHub Copilot coding agent</Blankslate.Heading>
          <Blankslate.Description>
            Let Copilot work independently in the background to complete tasks, and then monitor Copilot&apos;s
            progress.
          </Blankslate.Description>
          <Blankslate.SecondaryAction href="https://docs.github.com/en/copilot/how-tos/agents/copilot-coding-agent/enabling-copilot-coding-agent">
            Learn more about Copilot coding agent
          </Blankslate.SecondaryAction>
          {hasCEorCBAccess === true &&
            (showMemberRequests ? (
              <AccessRequestBanner
                enterprise={memberRequestEntities.enterprise}
                requestableOrgs={requestableOrgs}
                adminableOrgs={adminableOrgs}
              />
            ) : (
              <AccessDisabledBanner />
            ))}
          {hasCEorCBAccess === false && <UpgradeBanner />}
        </Blankslate>
      </ContentView.Container>
    </>
  )
}

try{ AgentsBlankslate.displayName ||= 'AgentsBlankslate' } catch {}