import type {Loop} from '../types/app'
import {useLoop} from './queries/use-loop'

/**
 * Loads the current loop using react-query, runs a selector function on it, and returns the result.
 */
export function useLoopLens<T>(selector: (loop: Loop | undefined | null) => T, version?: string): T {
  const {data: selectedData} = useLoop(selector, version)
  if (selectedData === undefined) {
    // maintain backwards compatibility with the previous version of this hook
    return selector(undefined)
  }

  return selectedData
}
