import type {CopilotMarkdownExtension} from '@github-ui/copilot-markdown/extension'

import {type NodeMeta, YamlBlockExtension} from '../yaml-block-extension'
import {PlanningTasklistBlock, type PlanningTasklistBlockProps} from './PlanningTasklistBlock'

const planningTasklistBlockAttribute = 'data-planning-tasklist-block'

const instance = new (class extends YamlBlockExtension<PlanningTasklistBlockProps> {
  override get dataAttribute(): `data-${string}` {
    return planningTasklistBlockAttribute
  }

  override isSupported(node: NodeMeta): boolean {
    return node.lang === 'yaml' && node.type === 'planning-tasklist'
  }

  override extractProps(node: NodeMeta): PlanningTasklistBlockProps {
    return {
      yaml: node.value,
      isStreaming: node.isStreaming ?? false,
    }
  }

  override createComponent(props: PlanningTasklistBlockProps): React.ReactNode {
    return <PlanningTasklistBlock {...props} />
  }
})()

export function planningTasklistExtension(): CopilotMarkdownExtension {
  return instance
}
