export class LoopsPlugin implements ImmersivePlugin {
  id = LOOPS_PLUGIN_ID

  displayName = LOOPS_PLUGIN_NAME

  constructor(
    completionsApiUrl: string,
    graphqlApiUrl: string,
    clientUrl: string,
    executionUrl: string,
    ssoOrgIDs: string[],
    previewUrl: string,
    realIp?: string,
  ) {
    const authTokenProvider = new CopilotAuthTokenProvider(ssoOrgIDs)
    this.client = new LoopsClient(clientUrl, authTokenProvider)
    this.service = new LoopsService(
      this.client,
      new GraphQLClient(graphqlApiUrl, authTokenProvider, this.client),
      new ChatCompletionsClient(completionsApiUrl, authTokenProvider, realIp),
      new IFrameCodeExecutor(executionUrl),
    )
    this.previewUrl = previewUrl
  }

  service: LoopsService
  client: LoopsClient

  previewUrl: string

  markdownExtensions = [loopBlocksExtension]

  skipSyncRouteToThread = true

  components: PluginComponent[] = [
    {
      id: 'loops-list',
      Component: LoopsView,
      routes: [LOOPS_REGEX],
    },
    {
      id: 'loop-detail',
      Component: LazyLoop,
      routes: [LOOP_REGEX],
    },
  ]

  get attachmentMenuContribution(): AttachmentMenuContribution | undefined {
    if (!copilotFeatureFlags.loopExecutionReferences) return undefined
    return {
      attachmentType: 'loop-execution',
      MenuItemComponent: LoopExecutionAttachmentMenuItem,
      PanelComponent: makeLoopExecutionPanelComponent(this.client),
    }
  }

  get previewComponents() {
    if (!copilotFeatureFlags.loopExecutionReferences) return undefined
    return {
      'loop-execution': withPreviewURL(this.previewUrl),
    }
  }

  // slashCommand = {
  //  key: 'loop',
  //  name: 'Loop',
  //  description: 'Automate recurring tasks using prompting',
  //  icon: LoopIcon,
  //  suggestions: [],
  //  execute: async (params: string, chatState: CopilotChatState, navigate: ReturnType<typeof useNavigate>) => {
  //    copilotLocalStorage.setLoopEntrypointMessage(params)
  //    navigate(COPILOT_LOOPS_PATH)
  //    return true
  //  },
  //  mode: {
  //    name: ModeSupportName.Loops,
  //    icon: LoopIcon,
  //  }
  // }

  navigationItems: NavigationItem[] = [
    {
      id: LOOPS_PLUGIN_ID,
      displayName: 'Loops',
      href: LOOPS_PATH,
      icon: LoopsIcon,
    },
  ]

  async overrideCreateMessageOptions(options: CreateMessageStreamingParams): Promise<CreateMessageStreamingParams> {
    return {
      ...options,
      mode: CHAT_MODE_LOOPS,
    }
  }
}
