import {fetchIssueTypes} from '@github-ui/item-picker-issue-type-tsq'
import {useQuery, useQueryClient} from '@github-ui/react-query'

const ORGANIZATION_ISSUE_TYPES_LIMIT = 25

export function useIssueTypesQuery({owner}: {owner: string | undefined}) {
  const queryClient = useQueryClient()
  const queryKey = ['copilot-immersive-issue-types', JSON.stringify(queryClient), owner]

  const queryFn = async () => {
    if (!owner) return []

    // TSQ implementation uses an empty query to fetch all issue types for the organization
    const response = await fetchIssueTypes(queryClient, {
      owner,
      query: '',
      count: ORGANIZATION_ISSUE_TYPES_LIMIT,
    })
    return response.issueTypes
  }

  return useQuery({
    queryKey,
    queryFn,
  })
}
