// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {CopilotChatIntents} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {getSelectedThread} from '@github-ui/copilot-chat/utils/get-selected-thread'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useCallback} from 'react'

import type {TimelineEventTextReference} from '../../timeline-events/timeline-events-types'
import type {PlanningSpec} from '../content-preview-types'

export function useCreateIssueFromSpec(spec: PlanningSpec) {
  const manager = useChatManager()
  const state = useChatState()

  const createIssue = useCallback(async () => {
    const specName = spec.name || spec.tag
    const thread = getSelectedThread(state)

    sendEvent('copilot.planning_tasklist', {
      target: 'PLANNING_TASK_SPEC_CREATE_ISSUE',
      mode: 'immersive',
      threadId: thread?.id,
      messageId: spec.messageId,
    })

    const timelineEvent: TimelineEventTextReference = {
      type: 'text',
      name: `timeline-event: {"type": "planning-spec-to-issue", "markdownContent": "Drafting '${specName}' spec as an issue..."}`,
    }

    const message = `
Create an issue based on the ${spec.tag} spec${spec.repository ? ` in the ${spec.repository} repository` : ''}.
- The issue title should be the same as the spec name.
- Use the spec content to draft the issue body. The issue body should include the full spec content and any relevant implementation details.
`

    await manager.sendChatMessage({
      thread,
      content: message,
      references: [timelineEvent],
      topic: state.currentTopic,
      context: state.context,
      customInstructions: state.customInstructions,
      model: state.model,
      intent: CopilotChatIntents.planningAgent,
    })
  }, [spec, state, manager])

  return {createIssue}
}
