import type {CopilotMarkdownExtension} from '@github-ui/copilot-markdown/extension'

import {type NodeMeta, YamlBlockExtension} from '../../yaml-block-extension'
import {PlanningSpecBlock, type PlanningSpecBlockProps} from './PlanningSpecBlock'

const planningSpecBlockAttribute = 'data-planning-spec-block'

const instance = new (class extends YamlBlockExtension<PlanningSpecBlockProps> {
  override get dataAttribute(): `data-${string}` {
    return planningSpecBlockAttribute
  }

  override isSupported(node: NodeMeta): boolean {
    return node.lang === 'yaml' && node.type === 'planning-spec'
  }

  override extractProps(node: NodeMeta): PlanningSpecBlockProps {
    return {
      yaml: node.value,
      isStreaming: node.isStreaming ?? false,
    }
  }

  override createComponent(props: PlanningSpecBlockProps): React.ReactNode {
    return <PlanningSpecBlock {...props} />
  }
})()

export function planningSpecExtension(): CopilotMarkdownExtension {
  return instance
}
