import {isFeatureEnabled} from '@github-ui/feature-flags'
import {fetchSearchAssignees as fetchSearchAssigneesRelay} from '@github-ui/item-picker-assignee-relay'
import {getActorCapabilities} from '@github-ui/item-picker-assignee-relay/utils/assignee-picker'
import {fetchAssignees as fetchAssigneesTsq} from '@github-ui/item-picker-assignee-tsq'
import {useQuery, useQueryClient} from '@github-ui/react-query'
import {useRelayEnvironment} from 'react-relay'

export function useAssigneesQuery({
  owner,
  repo,
  assignees,
}: {
  owner: string | undefined
  repo: string | undefined
  assignees: string[] | undefined
}) {
  const environment = useRelayEnvironment()
  const queryClient = useQueryClient()
  const capabilities = getActorCapabilities({includeAuthorableBots: false, includeAssignableBots: true})
  const tsqAssigneePickerEnabled = isFeatureEnabled('item_picker_assignee_tsq_migration')
  const queryKey = tsqAssigneePickerEnabled
    ? ['copilot-immersive-assignees', JSON.stringify(queryClient), capabilities, owner, repo, assignees]
    : ['copilot-immersive-assignees', JSON.stringify(environment), capabilities, owner, repo, assignees]

  const queryFn = async () => {
    if (!owner || !repo || !assignees) return []

    if (tsqAssigneePickerEnabled) {
      // TSQ implementation uses loginNames parameter to fetch specific assignees
      const response = await fetchAssigneesTsq(queryClient, {
        owner,
        repo,
        query: '',
        loginNames: assignees,
        capabilities,
      })
      return response.assignees
    } else {
      return await fetchSearchAssigneesRelay(environment, {
        owner,
        repo,
        assignees,
        capabilities,
      })
    }
  }

  return useQuery({
    queryKey,
    queryFn,
  })
}
