// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {LoopExecutionReference, NodeExecutionReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import type {Execution} from '../types/execution'
import type {Loop} from '../types/app'
import {getOutputNodes} from './loops'

export function makeLoopExecutionReference(loop: Loop, execution: Execution): LoopExecutionReference {
  const outputs: NodeExecutionReference[] = getOutputNodes(loop).map(node => {
    return {
      nodeID: node.id,
      type: node.type,
      title: node.title,
      value: execution.nodes[node.id]?.value,
    }
  })

  return {
    type: 'loop-execution' as const,
    loopID: loop.id,
    loopTitle: loop.title,
    createdAt: execution.createdAt,
    version: execution.loopVersion,
    executionID: execution.id,
    output: outputs,
  }
}
