import type {Loop, LoopGraph, Node, LoopValidationError} from '../types/app'
import {loopErrorType} from '../types/app'
import {inputTypeInfo} from '../types/input-types'
import {getLoopGraph} from '../utils/loops'
import {nodeHandlerRegistry} from './node-handler-registry'
import type {ValidationContext} from '../types/node-handler-interface'

/**
 * Type guard that validates if an unknown object conforms to the Loop type structure
 * @param obj - The object to validate
 * @returns A type predicate indicating if the object is a Loop
 */
export function isLoop(obj: unknown): obj is Loop {
  if (!obj || typeof obj !== 'object') {
    return false
  }

  const loop = obj as Partial<Loop>

  // Check if the object has the required Loop properties
  if (!('title' in loop) || typeof loop.title !== 'string' || !('nodes' in loop) || !Array.isArray(loop.nodes)) {
    return false
  }

  const validNodeTypes = nodeHandlerRegistry.getAllNodeTypes()
  const validInputTypes = Object.keys(inputTypeInfo)

  // Check that each node has required properties
  for (const node of loop.nodes || []) {
    if (!node || typeof node !== 'object') {
      return false
    }

    if (!('id' in node) || typeof node.id !== 'string') {
      return false
    }

    if (!('type' in node) || typeof node.type !== 'string' || !validNodeTypes.includes(node.type)) {
      return false
    }

    if (!('title' in node) || typeof node.title !== 'string') {
      return false
    }

    if (!('content' in node) || typeof node.content !== 'string') {
      return false
    }

    if (node.type === 'text') {
      if (!('metadata' in node) || typeof node.metadata !== 'object' || node.metadata === null) {
        return false
      }

      const inputMetadata = node.metadata

      if (!('inputType' in inputMetadata) || typeof inputMetadata.inputType !== 'string') {
        return false
      }

      if (!validInputTypes.includes(inputMetadata.inputType)) {
        return false
      }

      switch (inputMetadata.inputType) {
        case 'range': {
          const rangeInput = inputMetadata as {min?: number; max?: number}
          if (typeof rangeInput.min !== 'number' || typeof rangeInput.max !== 'number') {
            return false
          }
          break
        }

        case 'select': {
          const selectInput = inputMetadata as {options?: string[]}
          if (!Array.isArray(selectInput.options) || selectInput.options.length === 0) {
            return false
          }
          break
        }
      }
    }
  }

  return true
}

export function validateLoop(loop: Loop, context?: ValidationContext): LoopValidationError[] {
  // Early return if loop.nodes is not an array since further validations depend on it being a valid array
  if (!Array.isArray(loop.nodes)) {
    return [
      {
        error: `Loop has no nodes`,
        errorType: loopErrorType.MissingProperty,
        involvedNodes: [],
      },
    ]
  }

  const errors: LoopValidationError[] = validateLoopProperties(loop, context)

  const graph = getLoopGraph(loop.nodes)

  for (const edge of graph.edges) {
    const fromNode = loop.nodes.find(n => n.id === edge.from)
    const toNode = loop.nodes.find(n => n.id === edge.to)
    if (!fromNode || !toNode) {
      errors.push({
        error: `Node ${edge.to} references a nonexistent node {{${edge.from}}}`,
        errorType: loopErrorType.NonexistentNode,
        involvedNodes: [edge.to],
      })
    }
  }

  const cycle = findCycle(graph)
  if (cycle && cycle.length > 0) {
    // Add the first element to the end to make the cycle in the error message clearer
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const cycleList = [...cycle, cycle[0]!]
    errors.push({
      error: `Loop contains a cycle: ${cycleList.join(' → ')}`,
      errorType: loopErrorType.CycleDetected,
      involvedNodes: cycle,
    })
  }

  const disconnected = findDisconnectedNodes(graph)
  if (disconnected.length > 0) {
    errors.push({
      error: `Loop contains unreachable nodes: ${disconnected.join(', ')}`,
      errorType: loopErrorType.DisconnectedNode,
      involvedNodes: disconnected,
    })
  }
  return errors
}

function findCycle(graph: LoopGraph): string[] | null {
  const visited = new Set<string>()
  const stack = new Set<string>()
  const path: string[] = []

  // Helper function to perform DFS
  const dfs = (nodeId: string): string[] | null => {
    if (stack.has(nodeId)) {
      // Found a cycle, extract the cycle path
      const cycleStartIndex = path.indexOf(nodeId)
      return path.slice(cycleStartIndex)
    }
    if (visited.has(nodeId)) {
      return null
    }

    // Mark the current node as visited and add it to the recursion stack and path
    visited.add(nodeId)
    stack.add(nodeId)
    path.push(nodeId)

    // Recur for all the vertices adjacent to this vertex
    for (const edge of graph.edges) {
      if (edge.from === nodeId) {
        const cyclePath = dfs(edge.to)
        if (cyclePath) {
          return cyclePath
        }
      }
    }

    // Remove the current node from the recursion stack and path
    stack.delete(nodeId)
    path.pop()
    return null
  }

  // Call the helper function to detect cycle in different DFS trees
  for (const node of graph.nodes.values()) {
    if (!visited.has(node.id)) {
      const cyclePath = dfs(node.id)
      if (cyclePath) {
        return cyclePath
      }
    }
  }

  return null
}

function findDisconnectedNodes(graph: LoopGraph): string[] {
  const nodes = [...graph.nodes.values()]
  if (nodes.length === 0) {
    return []
  }

  const components: Array<Set<string>> = []
  const visited = new Set<string>()

  // Helper function to perform DFS and collect connected components
  const dfs = (nodeId: string, component: Set<string>) => {
    visited.add(nodeId)
    component.add(nodeId)

    for (const edge of graph.edges) {
      if (edge.from === nodeId && !visited.has(edge.to)) {
        dfs(edge.to, component)
      }
      if (edge.to === nodeId && !visited.has(edge.from)) {
        dfs(edge.from, component)
      }
    }
  }

  // Find all connected components
  for (const node of nodes) {
    if (!visited.has(node.id)) {
      const component = new Set<string>()
      dfs(node.id, component)
      components.push(component)
    }
  }

  // If there's only one component, there are no disconnected nodes
  if (components.length <= 1) {
    return []
  }

  // Find the largest component - we consider this the "main" graph
  const mainComponent = components.reduce(
    (largest, current) => (current.size > largest.size ? current : largest),
    new Set<string>(),
  )

  // All nodes not in the main component are considered disconnected
  const disconnectedNodes: string[] = []
  for (const node of nodes) {
    if (!mainComponent.has(node.id)) {
      disconnectedNodes.push(node.id)
    }
  }

  return disconnectedNodes
}

function validateLoopProperties(loop: Loop, context?: ValidationContext): LoopValidationError[] {
  let errors: LoopValidationError[] = []
  if (typeof loop.title !== 'string') {
    errors.push({
      error: `Loop is missing a title`,
      errorType: loopErrorType.MissingProperty,
      involvedNodes: [],
    })
  }
  if (loop.nodes.length === 0) {
    errors.push({
      error: `Loop has no nodes`,
      errorType: loopErrorType.MissingProperty,
      involvedNodes: [],
    })
  }
  for (const node of loop.nodes) {
    errors = errors.concat(validateNodeProperties(node, context))
  }
  return errors
}

function validateNodeProperties(node: Node, context?: ValidationContext): LoopValidationError[] {
  const errors: LoopValidationError[] = []
  if (typeof node.title !== 'string' || node.title.length === 0) {
    errors.push({
      error: `Node is missing a title`,
      errorType: loopErrorType.MissingProperty,
      involvedNodes: [node.id],
    })
  }

  const nodeSpecificErrors = nodeHandlerRegistry.validateNode(node, context)
  return errors.concat(nodeSpecificErrors)
}
