import type {LoopsAction} from './loops-action'
import type {LoopsState} from './loops-state'

export function loopsAppReducer(state: LoopsState, action: LoopsAction): LoopsState {
  switch (action.type) {
    case 'FOCUS_NODE': {
      return {...state, focusedNodeId: action.nodeId}
    }
    case 'HOVER_NODE': {
      return {...state, hoveredNodeId: action.nodeId}
    }
    case 'SET_VIEW': {
      return {...state, view: action.view}
    }
    case 'SET_SIDE_PANEL_VIEW': {
      return {...state, sidePanelView: action.view}
    }
    case 'SET_VERSION': {
      return {...state, version: action.version}
    }
    case 'SET_STATE': {
      return {...state, ...action.state}
    }
    case 'SHOW_LINK_COPIED_BANNER': {
      return {...state, showLinkCopiedBanner: true}
    }
    case 'HIDE_LINK_COPIED_BANNER': {
      return {...state, showLinkCopiedBanner: false}
    }
    case 'SHOW_DUPLICATED_BANNER': {
      return {...state, showDuplicatedBanner: true}
    }
    case 'HIDE_DUPLICATED_BANNER': {
      return {...state, showDuplicatedBanner: false}
    }
    default:
      return state
  }
}
