import type {NodeValue} from '../types/app'

export interface CodeExecutionOptions {
  code: string
  executionUrl: string
  timeoutMs?: number
  sandbox?: string
}

export interface CodeExecutionResult {
  success: boolean
  result?: NodeValue
  error?: string
}

export interface CodeExecutor {
  execute(code: string, nodeId: string, signal?: AbortSignal): Promise<CodeExecutionResult>
}

export class IFrameCodeExecutor implements CodeExecutor {
  readonly #executionUrl: string
  readonly #timeoutMs: number
  readonly #sandbox: string

  constructor(executionUrl: string, timeoutMs: number = 15000, sandbox: string = 'allow-scripts allow-same-origin') {
    this.#executionUrl = executionUrl
    this.#timeoutMs = timeoutMs
    this.#sandbox = sandbox
  }

  async execute(code: string, nodeId: string, signal?: AbortSignal): Promise<CodeExecutionResult> {
    if (!code) {
      return {success: true, result: ''}
    }

    return new Promise(resolve => {
      const iframe = document.createElement('iframe')
      const iframeUrl = `${this.#executionUrl}/code-node-execution.html`
      iframe.src = iframeUrl
      iframe.setAttribute('sandbox', this.#sandbox)

      let isResolved = false

      const cleanup = () => {
        if (handleMessage) {
          window.removeEventListener('message', handleMessage)
        }
        signal?.removeEventListener('abort', handleAbort)
        if (document.body.contains(iframe)) {
          document.body.removeChild(iframe)
        }
      }

      const resolveOnce = (result: CodeExecutionResult) => {
        if (isResolved) return
        isResolved = true
        cleanup()
        resolve(result)
      }

      const handleAbort = () => {
        iframe.contentWindow?.postMessage({type: 'cancel', nodeId}, this.#executionUrl)

        resolveOnce({success: false, error: 'Aborted'})
      }

      signal?.addEventListener('abort', handleAbort)

      const handleMessage = (event: MessageEvent) => {
        const allowedOrigin = new URL(this.#executionUrl, window.location.origin).origin
        if (event.origin !== allowedOrigin) {
          return
        }

        if (nodeId && event.data?.nodeId !== nodeId) {
          return
        }

        clearTimeout(timeout)

        if (event.data?.type === 'result') {
          resolveOnce({success: true, result: event.data.result})
        } else if (event.data?.type === 'error') {
          resolveOnce({success: false, error: event.data.result})
        }
      }

      const timeout = setTimeout(() => {
        iframe.contentWindow?.postMessage({type: 'cancel', nodeId}, this.#executionUrl)
        resolveOnce({success: false, error: 'Timeout: No response'})
      }, this.#timeoutMs)

      window.addEventListener('message', handleMessage)

      iframe.onerror = () => {
        clearTimeout(timeout)
        resolveOnce({success: false, error: 'Error: Failed to load execution environment'})
      }

      document.body.appendChild(iframe)
      iframe.onload = () => {
        try {
          iframe.contentWindow?.postMessage({type: 'execute', code, nodeId}, this.#executionUrl)
        } catch (error) {
          clearTimeout(timeout)
          resolveOnce({
            success: false,
            error: `Error: Failed to execute code - ${error instanceof Error ? error.message : 'Unknown error'}`,
          })
        }
      }
    })
  }
}
