import type {SelectedAgent} from '@github-ui/agent-sessions/types/session'
import {generateTaskPath} from '@github-ui/agent-sessions/utils/generate-task-path'
import type {RepositoryPickerRepository} from '@github-ui/item-picker/RepositoryPicker'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {Button} from '@primer/react'
import {useCallback, useEffect, useState} from 'react'

import type {PlanningSpec} from '../content-preview-types'
import {TaskActions} from '../planning-task-preview/TaskActions'
import {usePlanningTaskPullRequest, useStartAgentSession} from '../planning-task-preview/utils/agent-session'
import {specToTask} from './spec-to-task'
import {StartTaskDialog} from './StartTaskDialog'
import {useCreateIssueFromSpec} from './use-create-issue-from-spec'
import {useSpecRepository} from './use-spec-repository'
import {useTopReposQuery} from './use-top-repos-query'

interface SpecActionsProps {
  spec: PlanningSpec
  onError?: (error: Error | null) => void
}

export function SpecActions({spec, onError}: SpecActionsProps) {
  const [isMenuOpen, setIsMenuOpen] = useState(false)
  const [isModalOpen, setIsModalOpen] = useState(false)

  // Convert spec to task format for agent session hooks
  const specAsTask = specToTask(spec)

  // Use repository utility
  const {repositoryData, isLoading: isLoadingRepository} = useSpecRepository(spec)
  const {isLoading: loadingTopRepos, data: topRepos} = useTopReposQuery()

  // Use agent session hooks
  const {start: startTask, error} = useStartAgentSession(specAsTask)
  const {pullRequest, isLoading: isPullRequestDataLoading} = usePlanningTaskPullRequest(specAsTask)

  // Use create issue hook
  const {createIssue} = useCreateIssueFromSpec(spec)

  // Propagate error to parent component
  useEffect(() => {
    onError?.(error)
  }, [error, onError])

  // Pull request button logic
  const isMissionControlEnabled = useFeatureFlag('copilot_swe_agent_progress_commands')
  const pullRequestButtonHref = pullRequest
    ? isMissionControlEnabled
      ? generateTaskPath(pullRequest.global_relay_id)
      : `/${pullRequest.repository_nwo}/pull/${pullRequest.number}`
    : undefined
  const pullRequestButtonText = isMissionControlEnabled ? 'View task' : 'View pull request'

  // Button state validation
  const isSpecStreaming = spec.isStreaming ?? false
  const hasValidContent = !!spec.content?.trim()

  // Disable button if spec is streaming, no content, loading, repo not found, or currently starting
  const isButtonLoading = isSpecStreaming || isLoadingRepository || loadingTopRepos || isPullRequestDataLoading
  const isButtonDisabled = !hasValidContent || isButtonLoading

  // Start task handler - open modal dialog
  const handleStartTask = useCallback(() => {
    setIsModalOpen(true)
  }, [])

  // Handle modal cancel
  const handleModalCancel = useCallback(() => {
    setIsModalOpen(false)
  }, [])

  // Handle start from modal with selected options
  const handleModalStart = useCallback(
    (selectedRepo: RepositoryPickerRepository, selectedBranch: string, selectedAgent: SelectedAgent) => {
      startTask({
        nameWithOwner: selectedRepo.nameWithOwner,
        branch: selectedBranch,
        subAgent: selectedAgent?.subAgentSlug,
      })
      setIsModalOpen(false)
    },
    [startTask],
  )

  const handleCreateIssue = useCallback(() => {
    void createIssue()
  }, [createIssue])

  // If we have a pull request, show the PR button
  if (pullRequest) {
    return (
      <Button as="a" href={pullRequestButtonHref} variant="primary" size="small">
        {pullRequestButtonText}
      </Button>
    )
  }

  // Otherwise, show the task actions
  return (
    <>
      <TaskActions
        inactive={isButtonDisabled}
        isLoading={isButtonLoading}
        isMenuOpen={isMenuOpen}
        loadingAnnouncement="Loading spec…"
        menuItems={[
          {
            label: 'Create issue',
            onSelect: handleCreateIssue,
            disabled: isButtonDisabled || repositoryData?.hasIssuesEnabled === false,
          },
        ]}
        onMenuOpenChange={setIsMenuOpen}
        onStartClick={handleStartTask}
        primaryButtonText="Start task"
      />
      {isModalOpen && (
        <StartTaskDialog
          previewItem={spec}
          initialRepo={repositoryData}
          topRepos={topRepos || []}
          onStart={handleModalStart}
          onCancel={handleModalCancel}
        />
      )}
    </>
  )
}

try{ SpecActions.displayName ||= 'SpecActions' } catch {}