import type {AgentInfo} from '../types/session'

export const createMarkdownWithAgentLinks = (body: string, agentInfo?: AgentInfo): string => {
  return body.replace(/(@copilot|@![a-zA-Z0-9_-]+)/gi, match => {
    if (match.startsWith('@!')) {
      const mentionedAgent = match.substring(2).toLowerCase()

      if (agentInfo?.display_name) {
        const agentDisplayName = agentInfo.display_name.toLowerCase().replace(/\s+/g, '-')

        if (mentionedAgent === agentDisplayName) {
          // Preserve the original case of the mention
          return `[${match}](${agentInfo.doc_url})`
        }
      }

      return match
    }

    // Handle @copilot mentions
    if (match.toLowerCase() === '@copilot') {
      if (agentInfo?.display_name) {
        const agentDisplayName = agentInfo.display_name.toLowerCase()
        // Convert @copilot if the agent is Copilot, otherwise leave it as is
        if (agentDisplayName === 'copilot') {
          return `[${match}](https://gh.io/copilot-coding-agent-docs)`
        }
      }
    }

    return match
  })
}
