import {TasklistIcon, TriangleDownIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, ButtonGroup, IconButton} from '@primer/react'
import {useState} from 'react'

import type {PlanningSpec} from '../content-preview-types'
import styles from './SpecPreviewFooter.module.css'
import {useCreateSpecBreakdown} from './use-create-spec-breakdown'

export function SpecPreviewFooter({spec}: {spec: PlanningSpec}) {
  const [isTaskBreakdownMenuOpen, setIsTaskBreakdownMenuOpen] = useState(false)
  const {createBreakdown} = useCreateSpecBreakdown(spec)

  const disabled = spec.isStreaming || !spec.content

  return (
    <div className={styles.footer}>
      <div className={styles.footerText}>Consider breaking this up into multiple tasks</div>
      <ButtonGroup className={styles.buttonGroup}>
        <Button
          className={styles.button}
          leadingVisual={TasklistIcon}
          onClick={() => createBreakdown('task')}
          disabled={disabled}
          inactive={disabled}
        >
          Break down into smaller tasks
        </Button>

        <div className={styles.divider} />

        <ActionMenu open={isTaskBreakdownMenuOpen} onOpenChange={setIsTaskBreakdownMenuOpen}>
          <ActionMenu.Anchor>
            <IconButton
              aria-label="Task break down options…"
              className={styles.menuButton}
              icon={TriangleDownIcon}
              disabled={disabled}
              inactive={disabled}
            />
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList>
              <ActionList.Item onSelect={() => createBreakdown('issue')}>Break down into issues</ActionList.Item>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </ButtonGroup>
    </div>
  )
}

try{ SpecPreviewFooter.displayName ||= 'SpecPreviewFooter' } catch {}