import {isFeatureEnabled} from '@github-ui/feature-flags'
import {sendEvent} from '@github-ui/hydro-analytics'
import {CheckSpinner} from '@github-ui/mergebox'
import {SidebarListItem} from '@github-ui/pacer/SidebarListItem'
import {SidebarSection} from '@github-ui/pacer/SidebarNavigation'
import {useLocation} from '@github-ui/react-router'
import {
  CheckCircleFillIcon,
  ClockIcon,
  DotFillIcon,
  KebabHorizontalIcon,
  SkipIcon,
  StopIcon,
  type Icon,
} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton} from '@primer/react'
import {useRef} from 'react'
import {ConsecutiveCAPI401sProvider} from '../contexts/ConsecutiveCAPI401sContext'
import {useSSOChangeDetection} from '../hooks/use-sso-change-detection'
import {useTasks} from '../hooks/useTasks'
import type {OptimisticTask, UITask} from '../types/task'
import {COPILOT_CHAT_SPEC_TASK_EVENT_TYPE} from '../utils/constants'
import {extractSpecTaskThreadIdFromEventIdentifiers} from '../utils/extract-spec-task-thread-id'
import {generateTaskPath} from '../utils/generate-task-path'
import styles from './TaskList.module.css'

export function TasksListWrapper({
  viewAllLink,
  showTitle,
  trailingAction,
  onTaskClick,
}: {
  viewAllLink?: React.ReactNode
  showTitle?: boolean
  trailingAction?: React.ReactNode
  onTaskClick?: () => void
}) {
  return (
    <ConsecutiveCAPI401sProvider>
      <TasksList
        viewAllLink={viewAllLink}
        showTitle={showTitle}
        trailingAction={trailingAction}
        onTaskClick={onTaskClick}
      />
    </ConsecutiveCAPI401sProvider>
  )
}

function TasksList({
  viewAllLink,
  showTitle,
  trailingAction,
  onTaskClick,
}: {
  viewAllLink?: React.ReactNode
  showTitle?: boolean
  trailingAction?: React.ReactNode
  onTaskClick?: () => void
}) {
  const location = useLocation()
  const {tasks, isLoading} = useTasks()
  useSSOChangeDetection()

  const openTasks = tasks.filter(task => isOpenTask(task)).slice(0, 5)

  const isEmpty = openTasks.length === 0

  return (
    <>
      <SidebarSection
        title={showTitle ? 'Agent sessions' : undefined}
        isEmpty={isEmpty}
        isLoading={isLoading}
        trailingAction={trailingAction}
      >
        {openTasks.map(task => {
          const href = generateTaskPath(task.resource_global_id)
          const isSelected = location.pathname === href

          return (
            <TaskListEntry
              key={task.resource_id}
              task={task}
              href={href}
              isSelected={isSelected}
              secondaryText={task.nwo ?? task.pull?.repository_nwo ?? 'Initializing...'}
              onTaskClick={onTaskClick}
            />
          )
        })}
      </SidebarSection>
      {!isEmpty && viewAllLink}
    </>
  )
}

export interface TaskListEntryProps {
  task: UITask
  href: string
  isSelected: boolean
  secondaryText: string | React.ReactNode
  onTaskClick?: () => void
}

export function TaskListEntry({task, href, isSelected, secondaryText, onTaskClick}: TaskListEntryProps) {
  const anchorRef = useRef<HTMLButtonElement>(null)
  const isTaskPlanLinksEnabled = isFeatureEnabled('copilot_immersive_task_hyperlinking')

  const handleViewPullRequest = () => {
    sendEvent('dotcom_chat.activate', {
      target: 'TASK_ACTION_VIEW_PR',
      mode: 'immersive',
    })
    if (task.pull?.url) {
      window.location.href = task.pull.url
    }
  }

  const handleGoToConversation = () => {
    sendEvent('dotcom_chat.activate', {
      target: 'TASK_ACTION_GO_TO_CONVERSATION',
      mode: 'immersive',
    })
    const threadId = extractSpecTaskThreadIdFromEventIdentifiers(task.event_identifiers)
    if (threadId) {
      window.location.href = `/copilot/c/${threadId}`
    }
  }

  const trailingAction = (
    <ActionMenu anchorRef={anchorRef}>
      <ActionMenu.Anchor>
        <IconButton
          icon={KebabHorizontalIcon}
          aria-label="Manage session"
          variant="invisible"
          onClick={() =>
            sendEvent('dotcom_chat.activate', {
              target: 'TASK_CONTEXT_MENU',
              mode: 'immersive',
            })
          }
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay>
        <ActionList>
          <ActionList.Item onSelect={handleViewPullRequest}>View pull request</ActionList.Item>
          {task.event_type === COPILOT_CHAT_SPEC_TASK_EVENT_TYPE && isTaskPlanLinksEnabled && (
            <ActionList.Item onSelect={handleGoToConversation}>Go to parent conversation</ActionList.Item>
          )}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )

  return (
    <SidebarListItem
      href={href}
      text={isOptimisticTask(task) ? task.problemStatement : task.pull.title}
      leadingVisual={() => getLeadingVisualIconAttributes(task)}
      isSelected={isSelected}
      trailingAction={trailingAction}
      secondaryText={secondaryText}
      onClick={() => {
        onTaskClick?.()
        sendEvent('agent_sessions.task_view', {
          target: 'VIEW_TASK_FROM_MISSION_CONTROL',
          task_id: task.resource_global_id,
        })
      }}
    />
  )
}

export function isOpenTask(task: UITask): boolean {
  return !task.pull || (task.pull.state !== 'merged' && task.pull.state !== 'closed')
}

export function isOptimisticTask(task: UITask): task is OptimisticTask {
  return !!task.isOptimistic
}

export function getLeadingVisualIconAttributes(item: UITask): React.ReactElement<Icon> {
  const sessionState = item.latest_session_state
  const prState = item.pull?.state ?? 'unknown'

  if (sessionState === 'queued') {
    return <ClockIcon className={styles.clockIcon} />
  } else if (prState === 'open') {
    if (sessionState === 'waiting_for_user' || sessionState === 'completed') {
      return <CheckCircleFillIcon className={styles.checkCircleIcon} />
    }

    if (sessionState === 'failed' || sessionState === 'timed_out') {
      return <StopIcon className={styles.stopIcon} />
    }

    if (sessionState === 'in_progress') {
      return <CheckSpinner animated />
    }

    if (sessionState === 'idle') {
      return <DotFillIcon className={styles.dotFillIcon} />
    }

    if (sessionState === 'cancelled') {
      return <SkipIcon className={styles.skipIcon} />
    }
  }

  return <DotFillIcon className={styles.dotFillIcon} />
}

try{ TasksListWrapper.displayName ||= 'TasksListWrapper' } catch {}
try{ TasksList.displayName ||= 'TasksList' } catch {}
try{ TaskListEntry.displayName ||= 'TaskListEntry' } catch {}