// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {sendEvent} from '@github-ui/hydro-analytics'
import {ActionList} from '@primer/react'
import {useCallback, useEffect, useMemo, useRef} from 'react'

import type {PlanningTask as VersionedPlanningTask} from '../../components/ContentPreview/content-preview-types'
import {useContentPreview} from '../../components/ContentPreview/ContentPreviewContext'
import {useConvertAllToDraftIssues} from '../../components/ContentPreview/planning-task-preview/utils/use-convert-to-draft-issue'
import {useContentPreviewBlockContext} from '../ContentPreviewBlockContext'
import {useIsStreamingComplete} from '../hooks/use-is-streaming-complete'
import styles from './PlanningTasklistBlock.module.css'
import {SubtasksGroup} from './SubtasksGroup'
import {TasklistHeader} from './TasklistHeader'
import {TasklistItem} from './TasklistItem'
import {parseTasklistData, type PlanningTasklist} from './types'

export interface PlanningTasklistBlockProps {
  yaml: string
  isStreaming?: boolean
}

export function PlanningTasklistBlock({yaml, isStreaming}: PlanningTasklistBlockProps) {
  const isStreamingCompleted = useIsStreamingComplete(isStreaming)
  const openedTasksRef = useRef<Set<string>>(new Set())
  const {selectedThreadID: threadId} = useChatState()
  const {updateItem, openItem, openPreviewPane} = useContentPreview()
  const {messageId, messageIndex, setHasAutoOpenedPreviewPane} = useContentPreviewBlockContext()

  // Employ `useMemo + useRef` instead of `useState` to avoid asynchronous state updates
  // Since the order of versionedItems matters, we need to ensure that we call `updateItem` with the latest data
  // immediately after the YAML is changed.
  const tasklistRef = useRef<PlanningTasklist>({name: 'Tasklist', tasks: []})
  const tasklist = useMemo(() => {
    const parsedTaskData = parseTasklistData(yaml, threadId)
    if (parsedTaskData != null) {
      // eslint-disable-next-line react-hooks/refs
      tasklistRef.current = parsedTaskData
      return parsedTaskData
    } else {
      // Ignore bad data due to partially streamed YAML
      // eslint-disable-next-line react-hooks/refs
      return tasklistRef.current
    }
  }, [yaml, threadId])

  // Generate IDs for all tasks and update items for each one
  const taskItems: VersionedPlanningTask[] = useMemo(() => {
    return tasklist.tasks.map(taskItem => {
      const id = `planning-task:${taskItem.tag}#${messageIndex}` as const

      const {title, ...restOfTaskItem} = taskItem

      return {
        ...restOfTaskItem,
        name: title,
        messageId,
        id,
        type: 'planning-task',
        isUserEdited: false,
        isStreaming,
        subtaskTags: [],
      }
    })
  }, [tasklist, messageIndex, messageId, isStreaming])

  const {convertAllToDraftIssues} = useConvertAllToDraftIssues(taskItems.map(task => task.tag))

  const openTask = useCallback(
    (
      task: VersionedPlanningTask,
      options: {
        selectItem?: boolean
        event?: React.KeyboardEvent<HTMLElement> | React.MouseEvent<HTMLElement>
      } = {},
    ) => {
      const {selectItem, event} = options

      openItem(task.id, selectItem)
      openPreviewPane(event?.currentTarget as HTMLElement)
      setHasAutoOpenedPreviewPane(true)
    },
    [openItem, openPreviewPane, setHasAutoOpenedPreviewPane],
  )

  useEffect(() => {
    // Open task previews
    for (let i = 0; i < taskItems.length; i++) {
      const task = taskItems[i]
      updateItem(task!)

      // Only open once
      if ((isStreaming || isStreamingCompleted) && !openedTasksRef.current.has(task!.id)) {
        openedTasksRef.current.add(task!.id)
        openTask(task!, {selectItem: i === 0})
      }
    }
  }, [isStreaming, isStreamingCompleted, openTask, taskItems, updateItem])

  const onClick = useCallback(
    (task: VersionedPlanningTask, event?: React.KeyboardEvent<HTMLElement> | React.MouseEvent<HTMLElement>) =>
      openTask(task, {event}),
    [openTask],
  )

  useEffect(
    () => sendEvent('copilot.planning_tasklist', {type: 'BLOCK_RENDERED', mode: 'immersive', threadId}),
    [threadId],
  )

  useEffect(() => {
    if (isStreamingCompleted && taskItems.length === 0) {
      sendEvent('copilot.planning_tasklist', {type: 'NO_TASKS', mode: 'immersive', threadId})
    }
  }, [isStreamingCompleted, taskItems.length, threadId])

  const taskItemsMap = taskItems.map(task => (
    <TasklistItem isStreaming={!!isStreaming} key={task.id} onClick={e => onClick(task, e)} task={task} />
  ))

  return (
    <div className={styles.container}>
      <ActionList variant="full" showDividers>
        <TasklistHeader
          onConvertAllToDraftIssues={convertAllToDraftIssues}
          taskCount={taskItems.length}
          title={tasklist?.name ?? 'Tasklist'}
        />

        <SubtasksGroup isStreaming={!!isStreaming} taskCount={taskItems.length}>
          {taskItemsMap}
        </SubtasksGroup>
      </ActionList>
    </div>
  )
}

try{ PlanningTasklistBlock.displayName ||= 'PlanningTasklistBlock' } catch {}