// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {sendEvent} from '@github-ui/hydro-analytics'
import {DownloadIcon} from '@primer/octicons-react'
import {IconButton, SegmentedControl} from '@primer/react'
import {useCallback, useEffect, useMemo, useState} from 'react'

import type {PlanningSpec} from '../content-preview-types'
import {downloadFile} from '../download-file'
import {TaskErrorBanner} from '../planning-task-preview/TaskErrorBanner'
import {VersionSelector} from '../VersionSelector'
import {SpecActions} from './SpecActions'
import styles from './SpecToolbar.module.css'

type ViewMode = 'preview' | 'diff'

interface SpecToolbarProps {
  spec: PlanningSpec
  linesOfCode: number
  size: string
  isDiffable: boolean
  onViewModeChange: (mode: ViewMode) => void
}

export function SpecToolbar({spec, linesOfCode, size, isDiffable, onViewModeChange}: SpecToolbarProps) {
  const {selectedThreadID: threadId} = useChatState()
  const [viewMode, setViewMode] = useState<ViewMode>('preview')
  const [selectedVersion, setSelectedVersion] = useState<string | undefined>(undefined)

  // Error handling from SpecActions
  const [error, setError] = useState<Error | null>(null)
  const [dismissedError, setDismissedError] = useState<Error | null>(null)

  // Determine if we should show the error banner
  const shouldShowError = error && error !== dismissedError

  const handleDismissError = useCallback(() => {
    setDismissedError(error)
  }, [error])

  // Handle error from SpecActions
  const handleSpecActionsError = useCallback((newError: Error | null) => {
    setError(newError)
  }, [])

  // Clear error when spec changes
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setDismissedError(null)
  }, [spec.id])

  // Generate available modes based on isDiffable
  const availableModes: Array<[ViewMode, string]> = useMemo(() => {
    const modes: Array<[ViewMode, string]> = [['preview', 'Preview']]
    if (isDiffable) {
      modes.push(['diff', 'Diff'])
    }
    return modes
  }, [isDiffable])

  // Version change handler
  const handleVersionChange = useCallback((versionLabel: string) => {
    setSelectedVersion(versionLabel)
  }, [])

  const handleViewModeChange = useCallback(
    (i: number) => {
      const newViewMode = availableModes[i]?.[0] || 'preview'
      setViewMode(newViewMode)
      onViewModeChange(newViewMode)
      sendEvent('copilot.planning_tasklist', {
        target: 'PLANNING_TASK_SPEC_CHANGE_VIEW_MODE',
        option: newViewMode,
        threadId,
        messageId: spec.messageId,
      })
    },
    [availableModes, onViewModeChange, spec.messageId, threadId],
  )

  const handleDownload = useCallback(() => {
    const fileName = (() => {
      const baseName = spec.tag
      return selectedVersion !== undefined ? `${baseName}_${selectedVersion}.md` : `${baseName}.md`
    })()
    downloadFile(new File([spec.content], fileName))
    sendEvent('copilot.planning_tasklist', {
      target: 'PLANNING_TASK_SPEC_DOWNLOAD_FILE',
      mode: 'immersive',
      threadId,
      messageId: spec.messageId,
    })
  }, [selectedVersion, spec.content, spec.messageId, spec.tag, threadId])

  const handleCopy = useCallback(() => {
    sendEvent('copilot.planning_tasklist', {
      target: 'PLANNING_TASK_SPEC_COPY_CODE',
      mode: 'immersive',
      threadId,
      messageId: spec.messageId,
    })
  }, [spec.messageId, threadId])

  return (
    <>
      {shouldShowError && <TaskErrorBanner error={error} onDismiss={handleDismissError} />}
      <div className={styles.toolbar}>
        <div className={styles.toolbarLeft}>
          {availableModes.length > 1 && (
            <SegmentedControl aria-label="Spec view" onChange={handleViewModeChange}>
              {availableModes.map(([mode, label]) => (
                <SegmentedControl.Button key={mode} selected={viewMode === mode}>
                  {label}
                </SegmentedControl.Button>
              ))}
            </SegmentedControl>
          )}
          <VersionSelector item={spec} onVersionSelect={handleVersionChange} />
          <p className={styles.toolbarLoC}>
            {linesOfCode} {linesOfCode === 1 ? 'line' : 'lines'} · {size}
          </p>
        </div>
        <div className={styles.toolbarActions}>
          <CopyToClipboardButton textToCopy={spec.content} ariaLabel={'Copy spec content'} onCopy={handleCopy} />
          <IconButton aria-label="Download spec" icon={DownloadIcon} variant="invisible" onClick={handleDownload} />
          <SpecActions spec={spec} onError={handleSpecActionsError} />
        </div>
      </div>
    </>
  )
}

try{ SpecToolbar.displayName ||= 'SpecToolbar' } catch {}