import type {PlanningSpec, PlanningTask} from '../content-preview-types'

/**
 * Converts a PlanningSpec to PlanningTask format for agent session creation.
 * This allows specs to be used with the existing task-based agent session hooks.
 */
export function specToTask(spec: PlanningSpec): PlanningTask {
  return {
    // Copy shared properties from VersionedPreviewableContentBase
    messageId: spec.messageId,
    name: spec.name,
    isUserEdited: spec.isUserEdited,

    // Convert spec-specific properties to task format
    tag: spec.tag,
    repository: spec.repository,
    type: 'planning-task' as const,
    id: spec.id.replace('planning-spec:', 'planning-task:') as `planning-task:${string}#${number}`,
    description: spec.content, // Use spec content as task description
    isStreaming: spec.isStreaming,

    // Task-specific properties not present in specs
    dependencyTags: undefined,
    subtaskTags: undefined,
    aggregateTag: undefined,
  }
}
