import type {LoopsState, ViewType, SidePanelViewType} from '../state/loops-state'
import {defaultLoopsState, VIEW_TYPES, SIDE_PANEL_VIEW_TYPES} from '../state/loops-state'

/**
 * Type guard to check if a string is a valid ViewType
 */
function isValidViewType(value: string): value is ViewType {
  return Object.values(VIEW_TYPES).includes(value as ViewType)
}

/**
 * Type guard to check if a string is a valid SidePanelViewType
 */
function isValidSidePanelViewType(value: string): value is SidePanelViewType {
  return Object.values(SIDE_PANEL_VIEW_TYPES).includes(value as SidePanelViewType)
}

/**
 * Parse UI state from URL search parameters
 */
export function parseUIStateFromURL(searchParams: URLSearchParams): Partial<LoopsState> {
  const urlState: Partial<LoopsState> = {}

  const focusedNode = searchParams.get('focusedNode')
  if (focusedNode) {
    urlState.focusedNodeId = focusedNode
  }

  const view = searchParams.get('view')
  if (view && isValidViewType(view)) {
    urlState.view = view
  }

  const sidePanel = searchParams.get('sidePanel')
  if (sidePanel && isValidSidePanelViewType(sidePanel)) {
    urlState.sidePanelView = sidePanel
  }

  const version = searchParams.get('version')
  if (version) {
    urlState.version = version
  }

  return urlState
}

/**
 * Create URL search parameters from UI state
 */
export function createURLSearchParamsFromUIState(state: LoopsState): URLSearchParams {
  const params = new URLSearchParams()

  if (state.focusedNodeId) {
    params.set('focusedNode', state.focusedNodeId)
  }

  if (state.view !== defaultLoopsState.view) {
    params.set('view', state.view)
  }

  if (state.sidePanelView !== defaultLoopsState.sidePanelView) {
    params.set('sidePanel', state.sidePanelView)
  }

  if (state.version !== defaultLoopsState.version) {
    params.set('version', state.version)
  }

  return params
}

/**
 * Get initial UI state by merging defaults with URL parameters
 */
export function getInitialUIStateFromURL(searchParams: URLSearchParams): LoopsState {
  return {
    ...defaultLoopsState,
    ...parseUIStateFromURL(searchParams),
  }
}
