import {sendEvent} from '@github-ui/hydro-analytics'
import {load} from 'js-yaml'

export interface PlanningSpec {
  tag: string
  name: string
  repository?: string
  content: string
}

const isPlanningSpec = (obj: unknown): obj is PlanningSpec => {
  if (typeof obj !== 'object' || obj === null) return false

  // Check for required properties
  if (!('tag' in obj) || typeof obj.tag !== 'string') return false
  if (!('name' in obj) || typeof obj.name !== 'string') return false
  if (!('content' in obj) || typeof obj.content !== 'string') return false

  // Check optional repository field
  if ('repository' in obj && obj.repository != null && typeof obj.repository !== 'string') return false

  return true
}

/** Being extremely defensive about the types here allows us to safely handle partial data and bad model results. */
const fromUnknownSpec = (data: unknown): PlanningSpec | null => {
  if (typeof data !== 'object' || data == null) return null

  if (isPlanningSpec(data)) {
    return data
  }

  return null
}

export const parseSpecData = (yaml: string, threadId: string | null) => {
  try {
    const result = load(yaml)
    return fromUnknownSpec(result)
  } catch {
    sendEvent('copilot.planning_spec', {type: 'MALFORMED_YAML', mode: 'immersive', threadId})
    return null
  }
}
