import type {SelectedAgent} from '@github-ui/agent-sessions/types/session'
import type {RepositoryPickerRepository} from '@github-ui/item-picker/RepositoryPicker'
import {useCallback, useRef, useState} from 'react'

import type {PlanningTask} from '../../content-preview-types'
import {StartTaskDialog} from '../../planning-spec-preview/StartTaskDialog'
import {TaskActions} from '../TaskActions'
import {UnmergedDependenciesWarningDialog} from '../UnmergedDependenciesWarningDialog'
import type {StartAgentSessionOptions} from '../utils/agent-session'
import {useConvertToDraftIssue} from '../utils/use-convert-to-draft-issue'
import {useHasUnmergedDependencies} from '../utils/use-has-unmerged-dependencies'
import {useTaskRepositorySelection} from '../utils/use-task-repository-selection'
import styles from './NoPullRequestTaskToolbar.module.css'

interface NoPullRequestTaskToolbarProps {
  loading: boolean
  task: PlanningTask
  startTask: (options?: StartAgentSessionOptions) => void
}

export function NoPullRequestTaskToolbar({loading, task, startTask: startAgentSession}: NoPullRequestTaskToolbarProps) {
  const [isMenuOpen, setIsMenuOpen] = useState(false)
  const [isModalOpen, setIsModalOpen] = useState(false)
  const {convertToDraftIssue} = useConvertToDraftIssue(task)

  const buttonRef = useRef<HTMLButtonElement>(null)
  const [showWarningDialog, setShowWarningDialog] = useState(false)
  const hasUnmergedDependencies = useHasUnmergedDependencies(task)

  const {
    selectedRepo: taskRepo,
    topRepos,
    isLoading,
  } = useTaskRepositorySelection({
    externalLoading: loading,
    task,
  })

  const handleStartTask = useCallback(() => {
    if (hasUnmergedDependencies) {
      setShowWarningDialog(true)
      return
    }

    setIsModalOpen(true)
  }, [hasUnmergedDependencies])

  // Handle modal cancel
  const handleModalCancel = useCallback(() => {
    setIsModalOpen(false)
  }, [])

  // Handle start from modal with selected options
  const handleModalStart = useCallback(
    (selectedRepo: RepositoryPickerRepository, selectedBranch: string, selectedAgent: SelectedAgent | undefined) => {
      startAgentSession({
        nameWithOwner: selectedRepo.nameWithOwner,
        branch: selectedBranch,
        subAgent: selectedAgent?.subAgentSlug,
      })
      setIsModalOpen(false)
    },
    [startAgentSession],
  )

  const handleConvertToDraftIssue = useCallback(() => {
    void convertToDraftIssue()
  }, [convertToDraftIssue])

  return (
    <>
      <div className={styles.toolbarActions}>
        <TaskActions
          inactive={!taskRepo}
          isLoading={isLoading}
          isMenuOpen={isMenuOpen}
          loadingAnnouncement={isLoading ? 'Loading…' : 'Starting task…'}
          menuItems={[
            {
              disabled: taskRepo?.hasIssuesEnabled === false,
              label: 'Draft issue',
              onSelect: handleConvertToDraftIssue,
            },
          ]}
          onMenuOpenChange={setIsMenuOpen}
          onStartClick={handleStartTask}
          ref={buttonRef}
        >
          {showWarningDialog && (
            <UnmergedDependenciesWarningDialog
              buttonRef={buttonRef}
              onClose={() => setShowWarningDialog(false)}
              onSubmit={handleStartTask}
            />
          )}
        </TaskActions>
      </div>
      {isModalOpen && (
        <StartTaskDialog
          previewItem={task}
          initialRepo={taskRepo}
          topRepos={topRepos || []}
          onStart={handleModalStart}
          onCancel={handleModalCancel}
        />
      )}
    </>
  )
}

try{ NoPullRequestTaskToolbar.displayName ||= 'NoPullRequestTaskToolbar' } catch {}