import {ActionList} from '@primer/react'
import {LoopsClient} from '../service/loops-client'
import {LoopsIcon} from '@github-ui/pacer/CustomIcon'
import {useCallback, useState} from 'react'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import type {ActionListItemInput} from '@primer/react/deprecated'
import {SelectPanel} from '@primer/react/experimental'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {LoopExecutionReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {AttachmentMenuItemProps, AttachmentPanelProps} from '@github-ui/copilot-chat/plugin'
import {useQuery} from '@github-ui/react-query'
import styles from './LoopExecutionAttachmentMenuItem.module.css'
import {makeLoopExecutionReference} from '../utils/loop-execution-reference'

export function LoopExecutionAttachmentMenuItem({onSelect}: AttachmentMenuItemProps) {
  return (
    <ActionList.Item onSelect={onSelect}>
      <ActionList.LeadingVisual>
        <LoopsIcon />
      </ActionList.LeadingVisual>
      Loops&hellip;
    </ActionList.Item>
  )
}

export function makeLoopExecutionPanelComponent(client: LoopsClient) {
  return function LoopExecutionsSelectPanel(props: AttachmentPanelProps) {
    return <LoopExecutionsSelectPanelInner {...props} client={client} />
  }
}

interface LoopExecutionsSelectPanelProps extends AttachmentPanelProps {
  client: LoopsClient
}

function LoopExecutionsSelectPanelInner({onSubmit, onDismiss, client}: LoopExecutionsSelectPanelProps) {
  const manager = useChatManager()
  const {data: references, isError, isLoading} = useLoopsWithOutput(client)

  const [filter, setFilter] = useState('')

  const onSelect = useCallback(
    (executionID: string) => {
      if (!references) return

      const selected = references.find(ex => ex.executionID === executionID)
      if (selected) {
        manager.addReference(selected, 'loop-executions-select-panel')
      }
      onSubmit()
    },
    [onSubmit, references, manager],
  )

  const items: ActionListItemInput[] = references
    ? references
        .map(ex => ({text: ex.loopTitle, key: ex.executionID, description: stringifyOutput(ex.output[0]?.value)}))
        .filter(item => item.text.toLowerCase().includes(filter.toLowerCase()))
    : []

  return (
    // width is not actually a system prop
    // eslint-disable-next-line primer-react/no-system-props
    <SelectPanel
      open
      variant="modal"
      width="large"
      selectionVariant="instant"
      title="Select Loop output"
      onCancel={onDismiss}
      onSubmit={onSubmit}
    >
      <SelectPanel.Header>
        <SelectPanel.SearchInput
          loading={isLoading}
          onChange={e => setFilter(e.currentTarget.value)}
          placeholder="Search loops"
          aria-label="Search loops"
        />
      </SelectPanel.Header>
      <ActionList>
        {!isLoading && isError && (
          <SelectPanel.Message variant="error" size="inline">
            An error occurred
          </SelectPanel.Message>
        )}
        {!isLoading && items.length === 0 && (
          <SelectPanel.Message variant="empty" title="No loop output found">
            Try creating and running a loop to see output here
          </SelectPanel.Message>
        )}
        {items.map(item => (
          <ActionList.Item key={item.key} onSelect={() => onSelect(item.key as string)}>
            {item.text}

            <ActionList.Description variant="block" className={styles.itemDescription}>
              {item.description}
            </ActionList.Description>
          </ActionList.Item>
        ))}
      </ActionList>
    </SelectPanel>
  )
}

function useLoopsWithOutput(client: LoopsClient) {
  return useQuery({
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
    queryKey: ['loop-execution-references'],
    queryFn: () => getLoopsWithOutput(client),
  })
}

const expectedGetExecutionErrors: Array<number | undefined> = [404, 403]

async function getLoopsWithOutput(client: LoopsClient): Promise<LoopExecutionReference[]> {
  const loopsResult = await client.listLoops()
  if (!loopsResult.success) throw new Error(loopsResult.error)

  const executions = await Promise.all(
    loopsResult.data.map(async loop => {
      if (!loop.version) return null

      const executionResult = await client.getExecution(loop.id, loop.version, 'latest')

      if (!executionResult.success) {
        if (expectedGetExecutionErrors.includes(executionResult.httpStatus)) {
          return null
        }
        throw new Error(executionResult.error)
      }

      return executionResult.data
    }),
  )

  const presentExecutions = executions.filter(ex => !!ex)

  const references = presentExecutions.map(ex => {
    const matchingLoop = loopsResult.data.find(l => l.id === ex?.loopID)
    if (!matchingLoop) return null

    return makeLoopExecutionReference(matchingLoop, ex)
  })

  return references.filter(ref => !!ref)
}

function stringifyOutput(outputValue: unknown): string {
  if (typeof outputValue === 'string') return outputValue
  return JSON.stringify(outputValue)
}

try{ LoopExecutionAttachmentMenuItem.displayName ||= 'LoopExecutionAttachmentMenuItem' } catch {}
try{ LoopExecutionsSelectPanel.displayName ||= 'LoopExecutionsSelectPanel' } catch {}
try{ LoopExecutionsSelectPanelInner.displayName ||= 'LoopExecutionsSelectPanelInner' } catch {}