import type {RepositoryPickerRepository} from '@github-ui/item-picker/RepositoryPicker'
import {fetchRepository, fetchTopRepositories} from '@github-ui/item-picker/RepositoryPicker'
import {useQuery} from '@github-ui/react-query'
import {useCallback, useEffect, useState} from 'react'
import {useRelayEnvironment} from 'react-relay'

import type {PlanningTask} from '../../content-preview-types'
import {useContentPreview} from '../../ContentPreviewContext'

interface UseRepositorySelectionOptions {
  externalLoading?: boolean
  task: PlanningTask
}

export function useTaskRepositorySelection({externalLoading = false, task}: UseRepositorySelectionOptions) {
  const [ownerName, repoName] = task.repository?.split('/') ?? []
  const [selectedRepo, setSelectedRepo] = useState<RepositoryPickerRepository | undefined>(undefined)
  const {updateItem} = useContentPreview()
  const environment = useRelayEnvironment()

  const {data: topRepos = [], isLoading: isLoadingTopRepos} = useQuery({
    queryKey: ['copilot-immersive-top-repos', JSON.stringify(environment)],
    queryFn: async () => {
      return await fetchTopRepositories(environment, {first: 10})
    },
  })

  const {data: fetchedTaskRepo, isLoading: isLoadingFetchedTaskRepo} = useQuery({
    queryKey: ['copilot-immersive-current-repo', JSON.stringify(environment), ownerName, repoName],
    queryFn: async () => {
      if (!ownerName || !repoName) {
        return null
      }

      return await fetchRepository(environment, ownerName, repoName)
    },
  })

  const isLoading = externalLoading || isLoadingTopRepos || isLoadingFetchedTaskRepo

  const handleRepoSelect = useCallback(
    (repo: RepositoryPickerRepository | undefined) => {
      setSelectedRepo(repo)

      if (!repo) {
        return
      }

      updateItem({...task, isUserEdited: true, repository: repo.nameWithOwner})
    },
    [task, updateItem],
  )

  useEffect(() => {
    if (isLoading) {
      return
    }

    if (task.repository) {
      if (fetchedTaskRepo && fetchedTaskRepo.nameWithOwner !== selectedRepo?.nameWithOwner) {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setSelectedRepo(fetchedTaskRepo)
      }

      return
    }

    if (!selectedRepo && topRepos && topRepos.length > 0) {
      handleRepoSelect(topRepos[0])
    }
  }, [fetchedTaskRepo, handleRepoSelect, isLoading, selectedRepo, task.repository, topRepos])

  return {
    handleRepoSelect,
    isLoading,
    selectedRepo,
    topRepos,
  }
}
