import {StartTaskWarningDialog} from './StartTaskWarningDialog'

interface UnmergedDependenciesWarningDialogProps {
  buttonRef: React.RefObject<HTMLButtonElement | null>
  onClose: () => void
  onSubmit: () => void
}

export function UnmergedDependenciesWarningDialog({
  buttonRef,
  onClose,
  onSubmit,
}: UnmergedDependenciesWarningDialogProps) {
  return (
    <StartTaskWarningDialog
      buttonRef={buttonRef}
      description="This task has unmerged dependencies. Please consider waiting until all dependencies are completed before starting the task."
      onClose={onClose}
      onSubmit={onSubmit}
      title="Unmerged dependencies"
    />
  )
}

try{ UnmergedDependenciesWarningDialog.displayName ||= 'UnmergedDependenciesWarningDialog' } catch {}