// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {useChatManager} from '@github-ui/copilot-chat/utils/CopilotChatManagerContext'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useCallback, useEffect, useMemo} from 'react'

import {PlanningQuestionsForm} from '../../../components/PlanningQuestionsForm/PlanningQuestionsForm'
import {parseQuestionsData} from '../../../components/PlanningQuestionsForm/types'
import {useContentPreviewBlockContext} from '../../ContentPreviewBlockContext'

export interface PlanningQuestionsBlockProps {
  yaml: string
  isStreaming?: boolean
}

export function PlanningQuestionsBlock({yaml, isStreaming}: PlanningQuestionsBlockProps) {
  const {selectedThreadID: threadId, messages, currentReferences} = useChatState()
  const {messageIndex} = useContentPreviewBlockContext()
  const manager = useChatManager()

  const questions = useMemo(() => {
    const parsedData = parseQuestionsData(yaml, threadId)
    return parsedData ?? {name: 'Brainstorm Questions', outline: [], questions: []}
  }, [yaml, threadId])

  // The questions form is read-only if the thread progressed beyond this message.
  const isReadOnly = useMemo(() => messages.length > messageIndex + 1, [messages.length, messageIndex])

  const handleSubmitAnswers = useCallback(
    (message: string) => {
      sendEvent('copilot.planning_questions', {
        type: 'SUBMIT_ANSWERS_CLICKED',
        mode: 'immersive',
        threadId,
        totalQuestionsCount: questions.questions.length,
      })

      const thread = manager.getThreadById(threadId)
      void manager.sendChatMessage({
        thread,
        content: message,
        references: currentReferences,
      })
    },
    [threadId, questions.questions.length, manager, currentReferences],
  )

  useEffect(
    () => sendEvent('copilot.planning_questions', {type: 'BLOCK_RENDERED', mode: 'immersive', threadId}),
    [threadId],
  )

  return (
    <PlanningQuestionsForm
      className="mb-3"
      questions={questions}
      isStreaming={isStreaming}
      isReadOnly={isReadOnly}
      onSubmitAnswers={handleSubmitAnswers}
    />
  )
}

try{ PlanningQuestionsBlock.displayName ||= 'PlanningQuestionsBlock' } catch {}