import type {CopilotMarkdownExtension} from '@github-ui/copilot-markdown/extension'

import {type NodeMeta, YamlBlockExtension} from '../../yaml-block-extension'
import {PlanningQuestionsBlock, type PlanningQuestionsBlockProps} from './PlanningQuestionsBlock'

const instance = new (class extends YamlBlockExtension<PlanningQuestionsBlockProps> {
  override get dataAttribute(): `data-${string}` {
    return 'data-planning-questions-block'
  }

  override isSupported(node: NodeMeta): boolean {
    return node.lang === 'yaml' && node.type === 'planning-questions'
  }

  override extractProps(node: NodeMeta): PlanningQuestionsBlockProps {
    return {
      yaml: node.value,
      isStreaming: node.isStreaming ?? false,
    }
  }

  override createComponent(props: PlanningQuestionsBlockProps): React.ReactNode {
    return <PlanningQuestionsBlock {...props} />
  }
})()

export default function planningQuestionsExtension(): CopilotMarkdownExtension {
  return instance
}
