import {useState} from 'react'
import {useLoopsService} from '../contexts/LoopsServiceProvider'
import {logError} from '../utils/console'
import type {Loop} from '../types/app'
import {useQueryClient} from '@github-ui/react-query'
import type {Execution} from '../types/execution'
import {ErrorResult, SuccessResult} from '../service/result'
import {executionQueryKey} from './queries/use-execution'
import {latestVersion} from '../utils/versions'
import {useProgressHandler} from './use-progress-handler'

/**
 * Standalone hook for running loops from the overview without requiring loop context.
 * Unlike useRunLoop, this doesn't depend on URL params or current loop state.
 */
export function useRunLoopStandalone() {
  const service = useLoopsService()
  const queryClient = useQueryClient()
  const [isPreparing, setIsPreparing] = useState(false)
  const {createProgressHandler} = useProgressHandler()

  const runLoop = async (loop: Loop) => {
    setIsPreparing(true)

    try {
      // Create a fresh execution for this loop
      const createExecutionResult = await service.createExecution(loop.id, loop.version || latestVersion)
      if (!createExecutionResult.success) {
        throw new Error(`Failed to create execution: ${createExecutionResult.error}`)
      }

      const execution = createExecutionResult.data
      const version = loop.version || latestVersion
      const progressHandler = createProgressHandler(loop.id, version)

      const getExecution = (loopID: string, loopVersion: string, _executionID: string) => {
        const currentExecutionQueryKey = executionQueryKey(loopID, loopVersion)
        const currentExecution = queryClient.getQueryData<Execution | null>(currentExecutionQueryKey)
        return Promise.resolve(currentExecution ? SuccessResult(currentExecution) : ErrorResult('execution not found'))
      }

      // Set the initial execution in the cache
      const executionKey = executionQueryKey(loop.id, version)
      queryClient.setQueryData(executionKey, execution)

      setIsPreparing(false)

      await service.runPipeline(loop, execution.id, progressHandler, getExecution)
    } catch (error) {
      setIsPreparing(false)
      logError('Error running loop:', error)
      throw error
    }
  }

  const stopLoop = (loop: Loop) => {
    // Find the current execution for this loop
    const executionKey = executionQueryKey(loop.id, loop.version || latestVersion)
    const execution = queryClient.getQueryData<Execution | null>(executionKey)
    if (!execution) return

    service.stopPipeline(execution.id, () => {
      queryClient.invalidateQueries({queryKey: executionKey})
    })
  }

  return {runLoop, stopLoop, isPreparing}
}
