import {useMemo} from 'react'

import type {PlanningTask} from '../../content-preview-types'
import {useContentPreview} from '../../ContentPreviewContext'
import {usePlanningTaskPullRequests} from './agent-session'

export function useHasUnmergedDependencies(task: PlanningTask): boolean {
  const {items, versionedItems} = useContentPreview()
  const dependencies = useMemo(() => {
    return (
      task.dependencyTags
        ?.map(tag => {
          const versions = versionedItems.get(`planning-task:${tag}`)
          if (versions == null || versions.length === 0) return null

          return items.get(versions.at(-1)!) as PlanningTask | undefined
        })
        .filter(dependency => dependency != null) ?? []
    )
  }, [items, task.dependencyTags, versionedItems])
  const dependencyPrs = usePlanningTaskPullRequests(dependencies)
  return dependencyPrs.some(dep => dep.isLoading || dep.pullRequest == null || dep.pullRequest.state !== 'merged')
}
