import type {HydratedTask} from '@github-ui/agent-sessions/types/task'
import {generateTaskPath} from '@github-ui/agent-sessions/utils/generate-task-path'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {Button, Label} from '@primer/react'

import styles from './PullRequestTaskToolbar.module.css'

interface PullRequestTaskToolbarProps {
  pullRequest: HydratedTask['pull']
}

export function PullRequestTaskToolbar({pullRequest}: PullRequestTaskToolbarProps) {
  const isMissionControlEnabled = useFeatureFlag('copilot_swe_agent_progress_commands')

  const buttonHref = isMissionControlEnabled
    ? generateTaskPath(pullRequest.global_relay_id)
    : `/${pullRequest.repository_nwo}/pull/${pullRequest.number}`

  const buttonText = isMissionControlEnabled ? 'View task' : 'View pull request'

  return (
    <>
      <div className={styles.toolbarLeft}>
        <Label variant="accent" size="large" className={styles.toolbarRepo}>
          {pullRequest.repository_nwo}
        </Label>
      </div>
      <div className={styles.toolbarActions}>
        <Label variant={pullRequest.state === 'merged' ? 'success' : 'accent'} size="small">
          {pullRequest.state === 'merged' ? 'Merged' : 'In progress'}
        </Label>
        <Button as="a" href={buttonHref} variant="primary" size="small">
          {buttonText}
        </Button>
      </div>
    </>
  )
}

try{ PullRequestTaskToolbar.displayName ||= 'PullRequestTaskToolbar' } catch {}