import {sanitizeLoop} from './loops'
import type {Loop} from '../types/app'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {CopilotChatMessage} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {REFERENCE_TYPE_LOOP} from './constants'

/**
 * Extract a loop/pipeline from a chat message if it contains a loop reference.
 */
export function getLoopFromChatMessage(message: CopilotChatMessage): {messageId: string; pipeline: Loop} | undefined {
  for (const ref of message.references ?? []) {
    if (ref.type === REFERENCE_TYPE_LOOP) {
      if (isLoop(ref)) {
        const loop: Loop = {
          description: ref.description,
          id: ref.id,
          title: ref.title,
          owned: true,
          nodes: ref.nodes,
          updatedAt: new Date(message.createdAt).getTime(),
          visibility: 'private',
        }

        const sanitizedLoop = sanitizeLoop(loop, [])
        return {messageId: message.id, pipeline: sanitizedLoop}
      }
    }
  }
  return undefined
}

/**
 * Get the latest loop from chat by looking for a loop reference in the thread.
 */
export function getLatestLoop(
  messages: readonly CopilotChatMessage[],
  searchUserMessages = false,
): {messageId: string; pipeline: Loop} | undefined {
  for (const message of [...messages].reverse()) {
    if (message.role !== 'assistant' && !searchUserMessages) continue

    const loopResult = getLoopFromChatMessage(message)
    if (loopResult) {
      return loopResult
    }
  }
  return undefined
}

function isLoop(obj: unknown): obj is Loop {
  return !!obj && typeof obj === 'object' && 'title' in obj && 'nodes' in obj
}
