import {
  ConversationFeedbackDialog,
  type FeedbackDialogRef,
  // eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
} from '@github-ui/copilot-chat/components/ConversationFeedbackDialog'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatStateValue} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {sendEvent} from '@github-ui/hydro-analytics'
import {CommentIcon, BookIcon, GearIcon, KebabHorizontalIcon, UploadIcon, LightBulbIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, IconButton} from '@primer/react'
import {useRef, useState} from 'react'
import {CreateLoopFromJsonDialog} from '../CreateLoopFromJsonDialog'
import styles from './LoopsViewHeader.module.css'

export interface LoopsViewHeaderProps {
  showExamples?: boolean
  onShowExamples?: () => void
}

export function LoopsViewHeader({showExamples = true, onShowExamples}: LoopsViewHeaderProps) {
  const feedbackRef = useRef<FeedbackDialogRef>(null)
  const anchorRef = useRef<HTMLButtonElement>(null)
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false)
  const optedInToUserFeedback = useChatStateValue('optedInToUserFeedback')

  const feedbackButton = optedInToUserFeedback ? (
    <Button
      variant="link"
      onClick={() => {
        feedbackRef.current?.openDialog()
        sendEvent('dotcom_chat.activate', {
          target: 'USER_MENU_GIVE_FEEDBACK',
          mode: 'immersive',
        })
      }}
    >
      Give feedback
    </Button>
  ) : null

  return (
    <div className={styles.header}>
      <div className={styles.rightControls}>
        {feedbackButton}
        <IconButton
          icon={BookIcon}
          as="a"
          href="https://docs.github.com/copilot"
          aria-label="Copilot Loops documentation"
          target="_blank"
          rel="noopener noreferrer"
          variant="invisible"
          onClick={() => sendEvent('dotcom_chat.activate', {target: 'LOOPS_HELP_BUTTON_CLICKED', mode: 'loops'})}
        />
        <ActionMenu anchorRef={anchorRef}>
          <ActionMenu.Anchor>
            <IconButton
              icon={KebabHorizontalIcon}
              aria-label="Menu"
              variant="invisible"
              onClick={() => sendEvent('dotcom_chat.activate', {target: 'META_CONTEXT_MENU', mode: 'loops'})}
            />
          </ActionMenu.Anchor>

          <ActionMenu.Overlay width="small">
            <ActionList>
              <ActionList.Group>
                {!showExamples && onShowExamples && (
                  <ActionList.Item
                    onSelect={() => {
                      onShowExamples()
                      sendEvent('dotcom_chat.activate', {target: 'LOOPS_SHOW_EXAMPLES', mode: 'loops'})
                    }}
                  >
                    <ActionList.LeadingVisual>
                      <LightBulbIcon />
                    </ActionList.LeadingVisual>
                    Show examples
                  </ActionList.Item>
                )}
                <ActionList.Item
                  onSelect={() => {
                    setIsCreateDialogOpen(true)
                    sendEvent('dotcom_chat.activate', {
                      target: 'META_CONTEXT_MENU_CREATE_FROM_JSON',
                      mode: 'loops',
                    })
                  }}
                >
                  Create from JSON
                  <ActionList.LeadingVisual>
                    <UploadIcon />
                  </ActionList.LeadingVisual>
                </ActionList.Item>
              </ActionList.Group>
              <ActionList.Divider />
              <ActionList.Group>
                {optedInToUserFeedback && (
                  <ActionList.Item
                    onSelect={() => {
                      feedbackRef.current?.openDialog()
                      sendEvent('dotcom_chat.activate', {
                        target: 'META_CONTEXT_MENU_GIVE_FEEDBACK',
                        mode: 'immersive',
                      })
                    }}
                  >
                    Give feedback
                    <ActionList.LeadingVisual>
                      <CommentIcon />
                    </ActionList.LeadingVisual>
                  </ActionList.Item>
                )}
                <ActionList.LinkItem
                  href="/settings/copilot"
                  onClick={() =>
                    sendEvent('dotcom_chat.activate', {target: 'META_CONTEXT_MENU_SETTINGS', mode: 'loops'})
                  }
                >
                  <ActionList.LeadingVisual>
                    <GearIcon />
                  </ActionList.LeadingVisual>
                  Settings
                </ActionList.LinkItem>
              </ActionList.Group>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
        <ConversationFeedbackDialog ref={feedbackRef} mode="immersive" returnFocusRef={anchorRef} />
        <CreateLoopFromJsonDialog isOpen={isCreateDialogOpen} onClose={() => setIsCreateDialogOpen(false)} />
      </div>
    </div>
  )
}

try{ LoopsViewHeader.displayName ||= 'LoopsViewHeader' } catch {}