import {Dialog} from '@primer/react'

export function StartTaskWarningDialog({
  title,
  description,
  onClose,
  onSubmit,
  buttonRef,
}: {
  title: string
  description: string
  onClose: () => void
  onSubmit: () => void
  buttonRef: React.RefObject<HTMLButtonElement | null>
}) {
  return (
    <Dialog
      title={title}
      onClose={onClose}
      returnFocusRef={buttonRef}
      footerButtons={[
        {buttonType: 'default', content: 'Cancel', onClick: onClose},
        {
          buttonType: 'danger',
          content: 'Proceed to PR creation',
          onClick: () => {
            onSubmit()
            onClose()
          },
        },
      ]}
    >
      {description}
    </Dialog>
  )
}

try{ StartTaskWarningDialog.displayName ||= 'StartTaskWarningDialog' } catch {}