import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {useMemo} from 'react'

import type {PlanningTask} from '../content-preview-types'
import {MarkdownPreview} from '../MarkdownPreview'
import styles from './TaskPreview.module.css'
import {TaskToolbar as TaskPreviewHeader} from './toolbar'

interface TaskPreviewProps {
  task: PlanningTask
}

export function TaskPreview({task}: TaskPreviewProps) {
  const markdownContent = useMemo(() => {
    let content = task.description

    if (task.name) {
      content = `# ${task.name}\n\n${content}`
    }

    return content
  }, [task.name, task.description])

  return (
    <ConsecutiveCAPI401sProvider>
      <div className={styles.container}>
        <TaskPreviewHeader task={task} />
        <MarkdownPreview content={{value: markdownContent, name: `${task.tag}.md`}} fallbackToRaw hideHeadingAnchors />
      </div>
    </ConsecutiveCAPI401sProvider>
  )
}

try{ TaskPreview.displayName ||= 'TaskPreview' } catch {}