import {useEffect, useReducer, type Dispatch} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'
import {getInitialUIStateFromURL, createURLSearchParamsFromUIState} from '../utils/url-sync'
import type {LoopsAction} from '../state/loops-action'
import type {LoopsState} from '../state/loops-state'
import {loopsAppReducer} from '../state/loops-app-reducer'
import {updateSearchParams} from '@github-ui/history'

/**
 * Custom hook that manages UI reducer state with URL synchronization
 *
 * This hook:
 * 1. Initializes the reducer with state from URL params merged with defaults
 * 2. Automatically syncs state changes to the URL
 */
export function useLoopsReducer(): [LoopsState, Dispatch<LoopsAction>] {
  const [searchParams] = useSearchParams()

  // Initialize state with URL parameters merged with defaults
  const [state, dispatch] = useReducer(loopsAppReducer, getInitialUIStateFromURL(searchParams))

  // Sync state changes to URL
  useEffect(() => {
    const newParams = createURLSearchParamsFromUIState(state)

    // use updateSearchParams instead of react-router's setSearchParams to update the URL
    // to avoid re-rendering at the router root level
    updateSearchParams(newParams)
  }, [state, searchParams])

  return [state, dispatch]
}
