/**
 * Custom error class for loop-related errors with HTTP status information.
 */
export class LoopError extends Error {
  readonly httpStatus?: number

  constructor(message: string, httpStatus?: number) {
    super(message)
    this.httpStatus = httpStatus
    this.name = 'LoopError'
  }
}

/**
 * Type guard for checking if an error is a LoopError
 */
export function isLoopError(error: unknown): error is LoopError {
  return error instanceof LoopError
}
