import {fetchRepository} from '@github-ui/item-picker/RepositoryPicker'
import {useQuery} from '@github-ui/react-query'
import {useRelayEnvironment} from 'react-relay'

import type {PlanningSpec} from '../content-preview-types'

export function useSpecRepository(spec: PlanningSpec) {
  const [ownerName, repoName] = spec.repository?.split('/') ?? []
  const environment = useRelayEnvironment()

  const {data: repositoryData, isLoading} = useQuery({
    queryKey: ['copilot-immersive-spec-repo', JSON.stringify(environment), ownerName, repoName],
    queryFn: async () => {
      if (!ownerName || !repoName) {
        return null
      }

      return await fetchRepository(environment, ownerName, repoName)
    },
  })

  return {
    repositoryData,
    isLoading,
  }
}
