// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {CopilotChatIntents} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {getSelectedThread} from '@github-ui/copilot-chat/utils/get-selected-thread'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useCallback} from 'react'

import type {TimelineEventTextReference} from '../../../timeline-events/timeline-events-types'
import type {PlanningTask} from '../../content-preview-types'

export function useConvertToDraftIssue(planningTask: PlanningTask) {
  const manager = useChatManager()
  const state = useChatState()

  const convertToDraftIssue = useCallback(async () => {
    const taskName = planningTask.name || planningTask.tag

    sendEvent('copilot.planning_tasklist', {
      target: 'PLANNING_TASK_DRAFT_ISSUE',
      mode: 'immersive',
      threadId: getSelectedThread(state)?.id,
    })

    const timelineEvent: TimelineEventTextReference = {
      type: 'text',
      name: `timeline-event: {"type": "planning-task-draft-issue", "markdownContent": "Drafting task '${taskName}' as an issue..."}`,
    }

    const repositoryPart = planningTask.repository ? ` in repository ${planningTask.repository}` : ''
    const message = `
Create a draft issue using the content of the ${planningTask.tag} task${repositoryPart}.
`

    await manager.sendChatMessage({
      thread: getSelectedThread(state),
      content: message,
      references: [timelineEvent],
      topic: state.currentTopic,
      context: state.context,
      customInstructions: state.customInstructions,
      model: state.model,
      intent: CopilotChatIntents.planningAgent,
    })
  }, [manager, state, planningTask])

  return {convertToDraftIssue}
}

export function useConvertAllToDraftIssues(taskTags: string[]) {
  const manager = useChatManager()
  const state = useChatState()

  const convertAllToDraftIssues = useCallback(async () => {
    sendEvent('copilot.planning_tasklist', {
      target: 'PLANNING_TASK_DRAFT_ALL_ISSUES',
      mode: 'immersive',
      threadId: getSelectedThread(state)?.id,
    })

    const timelineEvent: TimelineEventTextReference = {
      type: 'text',
      name: `timeline-event: {"type": "planning-task-draft-issue", "markdownContent": "Drafting all tasks as issues..."}`,
    }

    const message = `
Create draft issues for all tasks with the following tags: ${taskTags.join(', ')}.
The tasks should be filed under a new parent issue. If the tasklist has a title, use that as the parent issue title.
`

    await manager.sendChatMessage({
      thread: getSelectedThread(state),
      content: message,
      references: [timelineEvent],
      topic: state.currentTopic,
      context: state.context,
      customInstructions: state.customInstructions,
      model: state.model,
      intent: CopilotChatIntents.planningAgent,
    })
  }, [manager, state, taskTags])

  return {convertAllToDraftIssues}
}
