import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {useCallback, useState} from 'react'

import {useFileInfo} from '../../../utils/content-preview-utils'
import type {File, PlanningSpec} from '../content-preview-types'
import {getPreviousVersion} from '../content-preview-types'
import {useContentPreview} from '../ContentPreviewContext'
import {DiffView} from '../DiffView'
import {MarkdownPreview} from '../MarkdownPreview'
import styles from './SpecPreview.module.css'
import {SpecPreviewFooter} from './SpecPreviewFooter'
import {SpecToolbar} from './SpecToolbar'

interface SpecPreviewProps {
  spec: PlanningSpec
}

type ViewMode = 'preview' | 'diff'

// Adapter function to convert PlanningSpec to File interface for DiffView
function specToFile(spec: PlanningSpec): File {
  return {
    messageId: spec.messageId,
    name: `${spec.tag}.md`,
    id: spec.id.replace('planning-spec:', 'file:') as `file:${string}#${number}`,
    type: 'file' as const,
    value: spec.content,
    language: 'markdown',
    timestamp: spec.timestamp,
    isStreaming: spec.isStreaming ?? false,
    isUserEdited: spec.isUserEdited,
  }
}

export function SpecPreview({spec}: SpecPreviewProps) {
  const {items, versionedItems} = useContentPreview()

  const [viewMode, setViewMode] = useState<ViewMode>('preview')

  const handleViewModeChange = useCallback((mode: ViewMode) => {
    setViewMode(mode)
  }, [])

  const previousVersion = getPreviousVersion<PlanningSpec>(spec, items, versionedItems)
  const isDiffable = !!previousVersion

  const previousSpecFile = previousVersion ? specToFile(previousVersion) : null
  const specFile = specToFile(spec)
  const {linesOfCode, size} = useFileInfo(specFile)

  return (
    <ConsecutiveCAPI401sProvider>
      <div className={styles.container}>
        <SpecToolbar
          spec={spec}
          linesOfCode={linesOfCode}
          size={size}
          isDiffable={isDiffable}
          onViewModeChange={handleViewModeChange}
        />
        <div className={styles.content}>
          {viewMode === 'preview' ? (
            <MarkdownPreview content={{value: specFile.value, name: specFile.name}} fallbackToRaw hideHeadingAnchors />
          ) : (
            <DiffView left={previousSpecFile!} right={specFile} view="unified" />
          )}
        </div>
        <SpecPreviewFooter spec={spec} />
      </div>
    </ConsecutiveCAPI401sProvider>
  )
}

try{ SpecPreview.displayName ||= 'SpecPreview' } catch {}