import {clsx} from 'clsx'
import {useTheme} from '@primer/styled-react'
import styles from './OnboardingCards.module.css'
import onboardingExp1Light from './onboarding-exp-1.png'
import onboardingExp1Dark from './onboarding-exp-1-dark.png'
import onboardingExp2Light from './onboarding-exp-2.png'
import onboardingExp2Dark from './onboarding-exp-2-dark.png'
import onboardingExp3Light from './onboarding-exp-3.png'
import onboardingExp3Dark from './onboarding-exp-3-dark.png'
import onboardingExp4Light from './onboarding-exp-4.png'
import onboardingExp4Dark from './onboarding-exp-4-dark.png'

interface OnboardingCard {
  step: string
  title: string
  description: string
  imageLight: string
  imageDark: string
  color: string
}

const cards: OnboardingCard[] = [
  {
    step: 'STEP 1',
    title: 'Describe what you want to create',
    description:
      'Describe what you want to create and watch your first loop take shape. Refine and iterate whenever you need.',
    imageLight: onboardingExp1Light,
    imageDark: onboardingExp1Dark,
    color: 'bgColor-accent-muted borderColor-accent-muted',
  },
  {
    step: 'STEP 2',
    title: 'Connect nodes to build your workflow',
    description:
      'Every loop is made of connected nodes, each designed for a specific task. Adjust their inputs, fine-tune their settings, and watch data flow seamlessly from one node to the next, like a clear, powerful and predictable visual pipeline.',
    imageLight: onboardingExp2Light,
    imageDark: onboardingExp2Dark,
    color: 'bgColor-muted borderColor-muted',
  },
  {
    step: 'STEP 3',
    title: 'Run and review results',
    description:
      'Run your loop to see results instantly. Outputs are rendered in rich markdown, making it easy to review, validate, and keep improving your workflow.',
    imageLight: onboardingExp3Light,
    imageDark: onboardingExp3Dark,
    color: 'bgColor-open-muted borderColor-open-muted',
  },
  {
    step: 'STEP 4',
    title: 'Share with your team',
    description:
      'Once your loop is ready, share it with your team. Organize, reuse, and grow your collection of loops into a powerhouse of workflows everyone can build on.',
    imageLight: onboardingExp4Light,
    imageDark: onboardingExp4Dark,
    color: 'bgColor-done-muted borderColor-done-muted',
  },
]

export function OnboardingCards() {
  const {resolvedColorScheme} = useTheme()
  const isDark = resolvedColorScheme === 'dark'

  return (
    <div className={styles.container}>
      {cards.map(card => (
        <div key={card.step} className={clsx(styles.card, 'color-shadow-small')}>
          {/* Left - content */}
          <div className={styles.cardContent}>
            <h4 className={styles.cardTitle}>{card.step}</h4>
            <p className={styles.cardDescription}>{card.description}</p>
          </div>
          {/* Right - image */}
          <div className={clsx(styles.cardImageContainer, card.color)}>
            <img src={isDark ? card.imageDark : card.imageLight} alt={card.title} className={styles.cardImage} />
          </div>
        </div>
      ))}
    </div>
  )
}

try{ OnboardingCards.displayName ||= 'OnboardingCards' } catch {}