import {sendEvent} from '@github-ui/hydro-analytics'
import {GitPullRequestIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'

interface ViewPullRequestButtonProps {
  pullUrl: string
  taskId: string
}

export function ViewPullRequestButton({pullUrl, taskId}: ViewPullRequestButtonProps) {
  const handleClick = () => {
    sendEvent('agent_sessions.task_view', {
      target: 'VIEW_PULL_REQUEST_BUTTON',
      pull_url: pullUrl,
      task_id: taskId,
    })
  }
  return (
    <Button
      as="a"
      href={pullUrl}
      target="_self"
      leadingVisual={GitPullRequestIcon}
      variant="primary"
      size="small"
      onClick={handleClick}
    >
      View pull request
    </Button>
  )
}

try{ ViewPullRequestButton.displayName ||= 'ViewPullRequestButton' } catch {}