import {CreateJobError, useCreateTask} from '@github-ui/agent-sessions/hooks/useCreateTask'
import {useSSOChangeDetection} from '@github-ui/agent-sessions/hooks/useSSOChangeDetection'
import {useTasks} from '@github-ui/agent-sessions/hooks/useTasks'
import type {HydratedTask} from '@github-ui/agent-sessions/types/task'
// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useCallback, useEffect, useMemo, useState} from 'react'

import type {PlanningTask} from '../../content-preview-types'

const EVENT_TYPE = 'copilot-chat-spec-task'

function getAgentSessionEventIdentifier(threadId: string | null, taskTag: string | undefined): string | undefined {
  if (!threadId || !taskTag) {
    return undefined
  }
  return `${EVENT_TYPE}::${threadId}::${taskTag}`
}

function useAgentSessionEventIdentifier(task: PlanningTask): string | undefined {
  const state = useChatState()
  return getAgentSessionEventIdentifier(state.selectedThreadID, task.tag)
}

export interface StartAgentSessionOptions {
  nameWithOwner?: string
  branch?: string
  subAgent?: string | null
}

export function useStartAgentSession(task: PlanningTask): {
  /** Starts the agent session that creates a pull request */
  start: (options?: StartAgentSessionOptions) => void
  /** Whether the agent session is starting up */
  isStarting: boolean
  /** Current error state, if any */
  error: Error | null
} {
  const {selectedThreadID: threadId} = useChatState()
  const eventId = useAgentSessionEventIdentifier(task)
  const [error, setError] = useState<Error | null>(null)

  // Clear error when task changes
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setError(null)
  }, [task.id])

  const handleError = useCallback(
    (err: Error) => {
      if (!(err instanceof CreateJobError)) {
        err = new Error('An unexpected error occurred. Please try again.', {cause: err})
      }

      setError(err)

      let status: number | undefined
      if (err && 'status' in err && typeof err.status === 'number') {
        status = err.status
      }

      sendEvent('copilot.spec_mode.pr_creation.failure', {
        // eslint-disable-next-line camelcase
        http_status: status,
        // eslint-disable-next-line camelcase
        error_message: err.message,
        mode: 'immersive',
        threadId,
      })
    },
    [threadId],
  )

  const {createTask, isCreating} = useCreateTask({
    onError: handleError,
  })

  const title = task.name
  const problemStatement = useMemo(() => {
    const statement = task.name ? `${task.name}\n\n${task.description}` : task.description
    return (statement || task.tag).trim()
  }, [task.name, task.description, task.tag])

  const start = useCallback(
    (options?: StartAgentSessionOptions) => {
      if (isCreating) {
        return
      }

      // Clear any previous error when starting a new attempt
      setError(null)

      sendEvent('copilot.planning_tasklist', {target: 'PLANNING_TASK_START', mode: 'immersive', threadId})

      const nameWithOwner = options?.nameWithOwner ?? task.repository
      if (!nameWithOwner) {
        handleError(new Error('Repository is required to start a task'))
        return
      }

      const repoParts = nameWithOwner.split('/')
      if (repoParts.length !== 2 || !repoParts[0] || !repoParts[1]) {
        handleError(new Error('Invalid repository format. Expected "owner/repo"'))
        return
      }

      if (!eventId) {
        handleError(new Error('Unable to generate task ID - thread or task tag missing'))
        return
      }

      createTask(
        {
          nwo: nameWithOwner,
          baseRef: options?.branch,
          selectedAgent: options?.subAgent ? {typeName: 'customSubAgent', subAgentSlug: options.subAgent} : undefined,
          problemStatement,
          title,
          eventType: EVENT_TYPE,
        },
        eventId,
      )
    },
    [createTask, eventId, handleError, isCreating, problemStatement, task.repository, threadId, title],
  )

  return {start, isStarting: isCreating, error}
}

interface PullRequestStatus {
  /** Pull request info if the task has been hydrated with PR data */
  pullRequest: HydratedTask['pull'] | undefined
  /** Whether the task PR data is loading */
  isLoading: boolean
}

/**
 * Returns the most recent non-closed pull requests associated with planning tasks, if any.
 */
export function usePlanningTaskPullRequests(tasks: PlanningTask[]): PullRequestStatus[] {
  const state = useChatState()
  const eventIds = tasks.map(task => getAgentSessionEventIdentifier(state.selectedThreadID, task.tag))
  // Detect SSO changes and clear cached tasks
  useSSOChangeDetection()
  const {tasks: agentTasks, isLoading: isLoadingAgentTasks} = useTasks({})

  const prsData = useMemo(() => {
    return eventIds.map(eventId => {
      if (!eventId || isLoadingAgentTasks || agentTasks.length === 0) {
        return {
          isLoading: !!eventId && isLoadingAgentTasks,
          pullRequest: undefined,
        }
      }

      // Find the agent task by searching the session event identifiers.
      // Don't compare against clientGeneratedId as optimistic tasks are ephemeral.
      const pullRequestStatuses = agentTasks
        .filter(t => t.event_identifiers?.includes(eventId))
        .map(t => ({
          isLoading: !!t?.isOptimistic,
          pullRequest: t.pull,
        }))

      return getLatestPullRequest(pullRequestStatuses)
    })
  }, [eventIds, agentTasks, isLoadingAgentTasks])

  return prsData
}

/**
 * Returns the most recent non-closed pull request associated with a single planning task, if any.
 */
export function usePlanningTaskPullRequest(task: PlanningTask | undefined | null): PullRequestStatus {
  const pullRequests = usePlanningTaskPullRequests(task ? [task] : [])
  return pullRequests[0] ?? {isLoading: false, pullRequest: undefined}
}

function getLatestPullRequest(pullRequests: PullRequestStatus[]): PullRequestStatus {
  if (pullRequests.length === 0) return {isLoading: false, pullRequest: undefined}

  let latestPullRequest: PullRequestStatus = {isLoading: false, pullRequest: undefined}
  for (const pr of pullRequests) {
    // if any PRs are still loading, we can't be sure which is the latest, so return loading state
    if (pr.isLoading) return {isLoading: true, pullRequest: undefined}

    // skip closed PRs in case the user has reopened an earlier one
    if (pr.pullRequest?.state === 'closed') continue

    const currentCreatedAt = pr.pullRequest?.created_at
    const latestCreatedAt = latestPullRequest.pullRequest?.created_at

    if (!currentCreatedAt) continue

    if (!latestCreatedAt || new Date(currentCreatedAt).getTime() > new Date(latestCreatedAt).getTime()) {
      latestPullRequest = pr
    }
  }

  return latestPullRequest
}
