import {LockIcon} from '@primer/octicons-react'
import styles from './SessionInitialMessage.module.css'
import type {Session} from '../../../types/session'

export const SessionInitialMessage = ({session}: {session?: Session}) => {
  if (session) {
    return (
      <div className={styles.container}>
        <LockIcon />
        <p className={styles.message}>
          Viewing session <span className="text-bold">{session.name}</span> only
        </p>
      </div>
    )
  }
}

try{ SessionInitialMessage.displayName ||= 'SessionInitialMessage' } catch {}