import {useQuery} from '@github-ui/react-query'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import type {Loop} from '../../types/app'

export const ALL_LOOPS_QUERY_KEY = 'all-loops'

export function useAllLoops() {
  const service = useLoopsService()

  return useQuery<Loop[]>({
    queryKey: [ALL_LOOPS_QUERY_KEY],
    queryFn: async () => {
      const result = await service.getAllLoops()
      if (!result.success) throw new Error(result.error)
      return result.data.sort((a, b) => b.updatedAt - a.updatedAt)
    },
    refetchOnMount: true,
  })
}
