const debouncedAnnounceFromElement = debounce(announceFromElement, 1000)

export interface LoopsViewProps {
  chatState: CopilotChatState
  plugin?: ImmersivePlugin
}

export function LoopsView({chatState, plugin}: LoopsViewProps) {
  if (!plugin || !isLoopsPlugin(plugin)) throw new Error('LoopsView can only be used with a LoopsPlugin')
  const [showExamples, setShowExamples] = useLocalStorage('loopsShowExamples', true)
  const defaultModel = useDefaultModel(chatState.availableModels)
  return (
    <LoopsServiceProvider value={plugin.service}>
      <AppContextProvider
        previewUrl={plugin.previewUrl}
        availableModels={chatState.availableModels}
        defaultModel={defaultModel}
        sendChatMessage={() => {}}
      >
        <PacerLayout data-testid="loops-layout">
          <PacerLayout.Header>
            <LoopsViewHeader showExamples={showExamples} onShowExamples={() => setShowExamples(true)} />
          </PacerLayout.Header>

          <PacerLayout.Sidebar>
            <CopilotNavigationWithContext />
          </PacerLayout.Sidebar>

          <PacerLayout.ColumnLeft>
            <LoopsViewInner chatState={chatState} showExamples={showExamples} setShowExamples={setShowExamples} />
          </PacerLayout.ColumnLeft>
        </PacerLayout>
      </AppContextProvider>
    </LoopsServiceProvider>
  )
}

interface LoopsViewInnerProps {
  chatState: CopilotChatState
  showExamples: boolean
  setShowExamples: (show: boolean) => void
}

function LoopsViewInner({chatState, showExamples, setShowExamples}: LoopsViewInnerProps) {
  const {data: loops, isLoading} = useAllLoops()
  const manager = useChatManager()
  const navigate = useNavigate()
  const loopsService = useLoopsService()
  const defaultModel = useDefaultModel(chatState.availableModels)
  const [viewMode, setViewMode] = useLocalStorage('loopsOverviewViewMode', 'output' as 'list' | 'output')
  // we only show the "Loops" title if the examples section is visible and placed above the loops list
  const showLoopsTitle = showExamples
  const [searchQuery, setSearchQuery] = useState('')
  const {chatQuotaExceeded, isLicensedLimited} = useEntitlement()
  const isInputDisabled = isLicensedLimited && chatQuotaExceeded
  const noResultsRef = useRef<HTMLDivElement>(null)

  // Filter loops based on search query
  const filteredLoops = useMemo(() => {
    if (!loops) {
      return loops
    }
    // Filter out loops with empty title AND empty nodes
    const nonEmptyLoops = loops.filter(loop => !(loop.title === '' && loop.nodes.length === 0))

    if (!searchQuery.trim()) {
      return nonEmptyLoops
    }
    const query = searchQuery.toLowerCase().trim()
    return nonEmptyLoops.filter(
      loop =>
        loop.title.toLowerCase().includes(query) ||
        (loop.description && loop.description.toLowerCase().includes(query)),
    )
  }, [loops, searchQuery])

  useEffect(() => {
    // Set the page title when component mounts
    setTitle('Loops · GitHub Copilot')

    // Preload Loop to warm the component for when users navigate to loops
    preloadLoopComponent()
  }, [])

  useEffect(() => {
    // clear out the thread on mount
    manager.selectThread(null, {includeThreads: false, clearTopic: true})
  }, [manager])

  const handleUserSubmit = useCallback(
    async (content: string) => {
      const trimmedContent = content.trim()
      if (trimmedContent === '') return

      sendEvent('dotcom_chat.activate', {target: 'OVERVIEW_INITIAL_CREATE', mode: 'loops'})

      const newLoopId = crypto.randomUUID()

      const opts = {scopeId: LOOPS_PLUGIN_ID}
      const thread = await manager.createThread(opts)
      await loopsService.createLoop(newLoopId)
      setLoopThreadId(newLoopId, thread.id)

      const chatMessageParams = {
        content: trimmedContent,
        model: defaultModel,
        references: [],
        thread,
        mode: CHAT_MODE_LOOPS,
      }

      manager.sendChatMessage(chatMessageParams)
      navigate(`${COPILOT_PATH}/l/${newLoopId}`)
    },
    [defaultModel, loopsService, manager, navigate],
  )

  const handleSubmitRef = useRef(handleUserSubmit)

  useEffect(() => {
    handleSubmitRef.current = handleUserSubmit
  }, [handleUserSubmit])

  useEffect(() => {
    const entrypointMessage = copilotLocalStorage.getLoopEntrypointMessage()
    if (entrypointMessage) {
      copilotLocalStorage.setLoopEntrypointMessage(null)
      handleSubmitRef.current(entrypointMessage.message)
    }
  }, [])

  useEffect(() => {
    if (noResultsRef.current) {
      debouncedAnnounceFromElement(noResultsRef.current, {assertive: true})
    }

    return () => {
      debouncedAnnounceFromElement.cancel()
    }
  }, [searchQuery, filteredLoops, isLoading])

  const createThreadWithLoop = async (loop: Loop) => {
    await loopsService.createLoop(loop)
    navigate(`${COPILOT_PATH}/l/${loop.id}`)
  }

  const handleViewModeChange = (mode: 'list' | 'output') => {
    setViewMode(mode)
  }

  const handleSearch = (query: string) => {
    setSearchQuery(query)
    sendEvent('dotcom_chat.activate', {target: 'LOOPS_SEARCH', mode: 'loops'})
  }

  return (
    <ContentView.Container width="small">
      <div className={styles.header}>
        <ContentView.Header>
          <ContentView.Title>Loops</ContentView.Title>
          <ContentView.Description>
            Automate repetitive tasks by simply describing them using natural language. Automate once. Loop forever.
          </ContentView.Description>
        </ContentView.Header>
        <div className={styles.input}>
          <ChatInput
            modes={[
              {
                name: ModeSupportName.Loops,
                icon: LoopIcon,
                submitLabel: 'Automate',
                placeholder: 'What would you like to automate?',
              },
            ]}
            size="large"
            disabled={isInputDisabled}
            onSubmit={handleUserSubmit}
          />
          {isInputDisabled && <FreeChatExceededBanner />}
        </div>
      </div>
      {!isLoading && showExamples && (
        <ContentView.Section>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Examples</h2>
            <IconButton
              icon={XIcon}
              aria-label="Dismiss examples"
              variant="invisible"
              size="small"
              onClick={() => {
                setShowExamples(false)
                sendEvent('dotcom_chat.activate', {target: 'LOOPS_DISMISS_EXAMPLES', mode: 'loops'})
              }}
            />
          </div>
          <div className={styles.examplesContainer}>
            {staffExamples.map(({altText: _altText, assetPath: _assetPath, loop: exampleLoop, icon: Icon}) => (
              <button
                key={exampleLoop.title}
                className={clsx(styles.exampleCard, 'color-shadow-small')}
                onClick={() => {
                  sendEvent('dotcom_chat.activate', {target: 'OVERVIEW_EXAMPLE_LOOP_SELECT', mode: 'loops'})
                  const newLoop: Loop = {
                    ...exampleLoop,
                    id: crypto.randomUUID(),
                    updatedAt: Date.now(),
                    owned: true,
                    visibility: 'private',
                  }
                  createThreadWithLoop(newLoop)
                }}
              >
                <div className={styles.exampleCardIconContainer}>
                  {Icon ? <Icon className={styles.exampleCardIcon} size={16} /> : null}
                </div>
                <div className={styles.exampleCardContent}>
                  <h3 className={styles.exampleCardTitle}>{exampleLoop.title}</h3>
                </div>
              </button>
            ))}
          </div>
        </ContentView.Section>
      )}
      {isLoading || (loops && loops.length > 0) ? (
        <ContentView.Section>
          {showLoopsTitle && (
            <div className={styles.sectionHeader}>
              <h2 className={styles.sectionTitle}>Loops</h2>
            </div>
          )}

          <div className={styles.searchContainer}>
            <SearchInput
              onSearch={handleSearch}
              placeholder="Search loops..."
              aria-label="Search loops"
              debounceDelay={300}
            />
            <ListModeToggle value={viewMode} onChange={handleViewModeChange} />
            <h2 className="sr-only">My loops</h2>
          </div>
          {searchQuery && filteredLoops && filteredLoops.length === 0 ? (
            <div className={styles.noResultsMessage} ref={noResultsRef}>
              No loops found matching &ldquo;{searchQuery}&rdquo;
            </div>
          ) : viewMode === 'list' ? (
            <ListBlock>
              <ListBlock.List loading={isLoading}>
                {filteredLoops?.map(item => (
                  <ListBlock.Item
                    key={item.id}
                    href={`${COPILOT_PATH}/l/${item.id}`}
                    onClick={() =>
                      sendEvent('dotcom_chat.activate', {target: 'OVERVIEW_USER_LOOP_SELECT', mode: 'loops'})
                    }
                  >
                    <ListBlock.Item.Title>{item.title}</ListBlock.Item.Title>
                    <ListBlock.Item.Description>{item.description}</ListBlock.Item.Description>
                    <ListBlock.Item.Actions>
                      <LoopsContextMenu loopId={item.id} />
                    </ListBlock.Item.Actions>
                  </ListBlock.Item>
                ))}
              </ListBlock.List>
            </ListBlock>
          ) : (
            <div className={outputListStyles.list}>
              {(filteredLoops || []).map(loop => (
                <LoopOutput key={loop.id} loop={loop} />
              ))}
            </div>
          )}
        </ContentView.Section>
      ) : null}
      {/* Get started section - only show when there are no loops */}
      {!isLoading && (!loops || loops.length === 0) && (
        <ContentView.Section>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Getting started</h2>
          </div>
          <OnboardingCards />
        </ContentView.Section>
      )}
    </ContentView.Container>
  )
}

try{ LoopsView.displayName ||= 'LoopsView' } catch {}
try{ LoopsViewInner.displayName ||= 'LoopsViewInner' } catch {}