import {Button} from '@primer/react'
import {useFeedbackDialog as useGenericFeedbackDialog} from './useFeedbackDialog'
import {useCallback} from 'react'
import {type RatingOption, frustratedIcon, frownIcon, smileIcon, grinIcon} from '@github-ui/user-feedback'

const ratingOptions: Array<RatingOption<'VERY_NEGATIVE' | 'NEGATIVE' | 'POSITIVE' | 'VERY_POSITIVE'>> = [
  {
    name: 'Hate it',
    value: 'VERY_NEGATIVE' as const,
    icon: frustratedIcon,
    color: 'veryDissatisfied',
  },
  {
    name: 'Not great',
    value: 'NEGATIVE' as const,
    icon: frownIcon,
    color: 'dissatisfied',
  },
  {
    name: 'It’s ok',
    value: 'POSITIVE' as const,
    icon: smileIcon,
    color: 'satisfied',
  },
  {
    name: 'Love it',
    value: 'VERY_POSITIVE' as const,
    icon: grinIcon,
    color: 'verySatisfied',
  },
]

export const useFeedbackDialog = () => useGenericFeedbackDialog('task-header', ratingOptions)

export function FeedbackButton() {
  const {openFeedback, FeedbackDialog} = useFeedbackDialog()
  const onClick = useCallback(() => openFeedback(), [openFeedback])

  return (
    <>
      <Button variant="link" className="f6" onClick={onClick}>
        Give feedback
      </Button>
      <FeedbackDialog />
    </>
  )
}

try{ FeedbackButton.displayName ||= 'FeedbackButton' } catch {}