import {AgentIcon, TriangleDownIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, ButtonGroup, IconButton} from '@primer/react'
import {forwardRef, type ReactNode} from 'react'

import styles from './TaskActions.module.css'

export interface TaskMenuItem {
  disabled?: boolean
  label: string
  onSelect: (() => void) | undefined
}

interface TaskActionsProps {
  children?: ReactNode
  inactive?: boolean
  isLoading: boolean
  isMenuOpen: boolean
  loadingAnnouncement?: string
  menuItems: TaskMenuItem[]
  onMenuOpenChange: (open: boolean) => void
  onStartClick: () => void
  primaryButtonText?: string
}

export const TaskActions = forwardRef<HTMLButtonElement, TaskActionsProps>(
  (
    {
      children,
      inactive,
      isLoading,
      isMenuOpen,
      loadingAnnouncement = 'Starting task…',
      menuItems,
      onMenuOpenChange,
      onStartClick,
      primaryButtonText = 'Start agent task',
    },
    ref,
  ) => {
    return (
      <ButtonGroup className={styles.buttonGroup}>
        <Button
          className={styles.button}
          inactive={inactive}
          leadingVisual={AgentIcon}
          loading={isLoading}
          loadingAnnouncement={loadingAnnouncement}
          onClick={onStartClick}
          ref={ref}
          variant="primary"
        >
          {primaryButtonText}
        </Button>

        {children}

        <div className={styles.divider} />

        <ActionMenu open={isMenuOpen} onOpenChange={onMenuOpenChange}>
          <ActionMenu.Anchor aria-label="Task options">
            <IconButton
              aria-label="Task options…"
              className={styles.menuButton}
              disabled={isLoading}
              icon={TriangleDownIcon}
              variant="primary"
            />
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList>
              {menuItems.map(item => (
                <ActionList.Item disabled={item.disabled} key={item.label} onSelect={item.onSelect}>
                  {item.label}
                </ActionList.Item>
              ))}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </ButtonGroup>
    )
  },
)

TaskActions.displayName = 'TaskActions'
