import {clsx} from 'clsx'
import {useCallback, useEffect, useState} from 'react'

import type {PlanningTask} from '../../content-preview-types'
import {TaskErrorBanner} from '../TaskErrorBanner'
import {usePlanningTaskPullRequest, useStartAgentSession} from '../utils/agent-session'
import {NoPullRequestTaskToolbar} from './NoPullRequestTaskToolbar'
import {PullRequestTaskToolbar} from './PullRequestTaskToolbar'
import styles from './TaskToolbar.module.css'

interface TaskToolbarProps {
  className?: string
  task: PlanningTask
}

export function TaskToolbar({className, task}: TaskToolbarProps) {
  const {pullRequest, isLoading: isPullRequestDataLoading} = usePlanningTaskPullRequest(task)
  const {start: startTask, error} = useStartAgentSession(task)
  const [dismissedError, setDismissedError] = useState<typeof error | null>(null)

  // Determine if we should show the error banner
  // Hide it if user has dismissed it or if there's no error
  const shouldShowError = error && error !== dismissedError

  const handleDismissError = useCallback(() => {
    setDismissedError(error)
  }, [error])

  // Clear error when task changes
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setDismissedError(null)
  }, [task.id])

  return (
    <>
      {shouldShowError && <TaskErrorBanner error={error} onDismiss={handleDismissError} />}
      <div className={clsx(styles.toolbar, className)}>
        {pullRequest ? (
          <PullRequestTaskToolbar pullRequest={pullRequest} />
        ) : (
          <NoPullRequestTaskToolbar loading={isPullRequestDataLoading} task={task} startTask={startTask} />
        )}
      </div>
    </>
  )
}

try{ TaskToolbar.displayName ||= 'TaskToolbar' } catch {}