import {AgentsPlugin} from '@github-ui/agent-sessions/agents-plugin'
import {TasksPlugin} from '@github-ui/agent-sessions/tasks-plugin'
import type {HandleUserSubmit} from '@github-ui/agent-sessions/types/user-submit'
import type {ImmersivePlugin} from '@github-ui/copilot-chat/plugin'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {LoopsPlugin} from '@github-ui/copilot-loops'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {SparkPlugin} from '@github-ui/spark'
import type {MutableRefObject} from 'react'
import {useMemo} from 'react'

export interface UseImmersivePluginsPayload {
  loopsEnabled?: boolean
  sparkEnabled?: boolean
  agentsEnabled?: boolean
  apiURL?: string
  graphqlApiUrl?: string
  loopsClientUrl?: string
  loopsExecutionUrl?: string
  ssoOrganizations?: Array<{id: string}>
  previewUrl?: string
  realIp?: string
  dashboardModulesEnabled?: boolean
}

export interface UseImmersivePluginsOptions {
  payload: UseImmersivePluginsPayload
  handleUserSubmitRef?: MutableRefObject<HandleUserSubmit>
}

export function useImmersivePlugins({payload, handleUserSubmitRef}: UseImmersivePluginsOptions): ImmersivePlugin[] {
  const showAgentsEmptyState = isFeatureEnabled('copilot_chat_agents_empty_state')
  const showSparkEmptyState = isFeatureEnabled('copilot_spark_empty_state')
  const isTasksEnabled = useFeatureFlag('copilot_swe_agent_progress_commands')
  const isAgentTaskListEnabled = useFeatureFlag('copilot_agent_task_list_v2')

  const plugins = useMemo(() => {
    const pluginsList: ImmersivePlugin[] = []

    if (copilotFeatureFlags.loopsPlugin && (payload.loopsEnabled ?? true)) {
      pluginsList.push(
        new LoopsPlugin(
          payload.apiURL ?? '',
          payload.graphqlApiUrl ?? '',
          payload.loopsClientUrl ?? '',
          payload.loopsExecutionUrl ?? '',
          payload.ssoOrganizations?.map(o => o.id) ?? [],
          payload.previewUrl ?? '',
          payload.realIp ?? '',
        ),
      )
    }

    if (payload.sparkEnabled || showSparkEmptyState) {
      pluginsList.push(new SparkPlugin(payload.sparkEnabled))
    }

    if (payload.agentsEnabled || showAgentsEmptyState) {
      // Use dashboardModulesEnabled if provided, otherwise calculate from feature flags
      const shouldCreateTaskFromList =
        payload.dashboardModulesEnabled !== undefined
          ? payload.dashboardModulesEnabled
          : isAgentTaskListEnabled && isTasksEnabled

      pluginsList.push(new AgentsPlugin(shouldCreateTaskFromList, handleUserSubmitRef, payload.agentsEnabled ?? false))
    }

    if (isTasksEnabled) {
      pluginsList.push(new TasksPlugin())
    }

    return pluginsList
  }, [
    payload.loopsEnabled,
    payload.sparkEnabled,
    payload.agentsEnabled,
    payload.apiURL,
    payload.graphqlApiUrl,
    payload.loopsClientUrl,
    payload.loopsExecutionUrl,
    payload.ssoOrganizations,
    payload.previewUrl,
    payload.realIp,
    payload.dashboardModulesEnabled,
    showSparkEmptyState,
    showAgentsEmptyState,
    isTasksEnabled,
    isAgentTaskListEnabled,
    handleUserSubmitRef,
  ])

  return plugins
}
