import {ActionMenuOverlay} from '@github-ui/copilot-chat/components/PortalContainerUtils'
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, CounterLabel, IconButton} from '@primer/react'

interface TasklistHeaderProps {
  onConvertAllToDraftIssues: () => void
  taskCount: number
  title: string
}

export function TasklistHeader({onConvertAllToDraftIssues, taskCount, title}: TasklistHeaderProps) {
  return (
    <ActionList.Heading as="h4" className="mx-3 mt-3 mb-1 d-flex flex-items-center">
      {title}
      <CounterLabel className="ml-2 pb-1">{taskCount}</CounterLabel>
      {taskCount > 0 && (
        <div className="flex-justify-end d-flex flex-1">
          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton aria-label={`Tasklist '${title}' options`} icon={KebabHorizontalIcon} variant="invisible" />
            </ActionMenu.Anchor>

            <ActionMenuOverlay>
              <ActionList>
                <ActionList.Item onSelect={onConvertAllToDraftIssues}>Draft all as issues</ActionList.Item>
              </ActionList>
            </ActionMenuOverlay>
          </ActionMenu>
        </div>
      )}
    </ActionList.Heading>
  )
}

try{ TasklistHeader.displayName ||= 'TasklistHeader' } catch {}