import {VersionName} from '@github-ui/copilot-chat/components/VersionName'
// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {disableStreamingFadeIn} from '@github-ui/copilot-markdown'
import {sendEvent} from '@github-ui/hydro-analytics'
import {NoteIcon} from '@primer/octicons-react'
import {ActionList, Spinner} from '@primer/react'
import {useCallback, useEffect, useMemo} from 'react'

import type {
  PlanningSpec as VersionedPlanningSpec,
  VersionedPreviewableContentBase,
} from '../../../components/ContentPreview/content-preview-types'
import {getRevisionNumber} from '../../../components/ContentPreview/content-preview-types'
import {useContentPreview} from '../../../components/ContentPreview/ContentPreviewContext'
import {useContentPreviewBlockContext} from '../../ContentPreviewBlockContext'
import {useIsStreamingComplete} from '../../hooks/use-is-streaming-complete'
import {useSyncState} from '../../hooks/use-sync-state'
import styles from './PlanningSpecBlock.module.css'
import {parseSpecData} from './types'

export interface PlanningSpecBlockProps {
  yaml: string
  isStreaming?: boolean
}

export function PlanningSpecBlock({yaml, isStreaming}: PlanningSpecBlockProps) {
  const isStreamingCompleted = useIsStreamingComplete(isStreaming)
  const {selectedThreadID: threadId} = useChatState()
  const {updateItem, openItem, openPreviewPane} = useContentPreview()
  const {messageId, messageIndex, messageTimestamp, setHasAutoOpenedPreviewPane} = useContentPreviewBlockContext()

  const parseData = useCallback((input: string) => parseSpecData(input, threadId), [threadId])
  const spec = useSyncState(yaml, parseData, null)

  // Generate ID for spec and update item (only when spec exists)
  const specItem: VersionedPlanningSpec | null = useMemo(() => {
    if (!spec) return null

    const id = `planning-spec:${spec.tag}#${messageIndex}` as const

    return {
      name: spec.name,
      tag: spec.tag,
      repository: spec.repository,
      content: spec.content,
      messageId,
      id,
      type: 'planning-spec',
      isUserEdited: false,
      isStreaming,
      timestamp: new Date(messageTimestamp),
    }
  }, [isStreaming, messageId, messageIndex, messageTimestamp, spec])

  const openSpec = useCallback(
    (item: VersionedPlanningSpec, options: {selectItem?: boolean} = {}) => {
      const {selectItem} = options

      openItem(item.id, selectItem)
      openPreviewPane()
      setHasAutoOpenedPreviewPane(true)
    },
    [openItem, openPreviewPane, setHasAutoOpenedPreviewPane],
  )

  useEffect(() => {
    if (specItem) {
      updateItem(specItem)

      // Only open once
      if (isStreaming || isStreamingCompleted) {
        openSpec(specItem, {selectItem: true})
      }
    }
  }, [isStreaming, isStreamingCompleted, openSpec, specItem, updateItem])

  const onClick = useCallback(() => {
    if (specItem) {
      openSpec(specItem)
    }
  }, [openSpec, specItem])

  useEffect(() => sendEvent('copilot.planning_spec', {type: 'BLOCK_RENDERED', mode: 'immersive', threadId}), [threadId])

  const getIcon = () => {
    if (isStreaming) {
      return <Spinner size="small" className={disableStreamingFadeIn} />
    }

    return <NoteIcon />
  }

  return <PlanningSpecBlockDisplay previewItem={specItem} onClick={onClick} getIcon={getIcon} />
}

export interface PlanningSpecBlockDisplayProps {
  previewItem?: VersionedPreviewableContentBase | null
  getIcon?: () => React.ReactNode
  onClick?: () => void
}

export function PlanningSpecBlockDisplay({previewItem, onClick, getIcon}: PlanningSpecBlockDisplayProps) {
  const {versionedItems} = useContentPreview()
  const version = previewItem ? getRevisionNumber(previewItem.id, versionedItems) : null

  return (
    <div className={styles.container}>
      <ActionList variant="full" showDividers>
        <ActionList.Item onSelect={onClick} className={styles.item}>
          <ActionList.LeadingVisual>{getIcon?.() || <NoteIcon />}</ActionList.LeadingVisual>
          <div className={styles.title}>{previewItem?.name ?? ''}</div>
          {version !== null && (
            <ActionList.TrailingVisual>
              <VersionName version={version} />
            </ActionList.TrailingVisual>
          )}
        </ActionList.Item>
      </ActionList>
    </div>
  )
}

try{ PlanningSpecBlock.displayName ||= 'PlanningSpecBlock' } catch {}
try{ PlanningSpecBlockDisplay.displayName ||= 'PlanningSpecBlockDisplay' } catch {}