import {sendEvent} from '@github-ui/hydro-analytics'
import {load} from 'js-yaml'

export interface PlanningQuestions {
  name: string
  outline: string[]
  questions: PlanningQuestion[]
}

export interface PlanningQuestion {
  question: string
  suggestions?: string[]
}

const isPlanningQuestion = (obj: unknown): obj is PlanningQuestion => {
  if (typeof obj !== 'object' || obj === null) return false
  if (!('question' in obj) || typeof obj.question !== 'string') return false

  // suggestions is optional, but if present, must be an array of strings
  if ('suggestions' in obj) {
    if (!Array.isArray(obj.suggestions)) return false
    // Validate that all suggestions are strings
    return obj.suggestions.every(suggestion => typeof suggestion === 'string')
  }

  return true
}

const fromUnknown = (data: unknown): PlanningQuestions | null => {
  if (typeof data !== 'object' || data == null) return null

  const name = 'name' in data && typeof data.name === 'string' ? data.name : 'Brainstorm Questions'
  const item: PlanningQuestions = {name, outline: [], questions: []}

  if ('outline' in data && Array.isArray(data.outline)) {
    for (const outlineItem of data.outline) {
      if (typeof outlineItem !== 'string') continue
      item.outline.push(outlineItem)
    }
  }

  if ('questions' in data && Array.isArray(data.questions)) {
    for (const questionData of data.questions) {
      if (typeof questionData !== 'object' || questionData == null) continue
      if (!isPlanningQuestion(questionData)) continue
      item.questions.push(questionData)
    }
  }

  return item
}

export const parseQuestionsData = (yaml: string, threadId: string | null) => {
  try {
    const result = load(yaml)
    return fromUnknown(result)
  } catch {
    sendEvent('copilot.planning_questions', {type: 'MALFORMED_YAML', mode: 'immersive', threadId})
    return null
  }
}
