import {reactFetchJSON} from '@github-ui/verified-fetch'
import {CopilotAuthTokenProvider} from '@github-ui/copilot-auth-token'
import {validateGraphQL} from '../utils/graphql'
import {isLoopsServiceGraphQLExecutionEnabled} from '../utils/feature-flags'
import type {LoopsClient} from './loops-client'

export interface NodeExecutionContext {
  loopId: string
  version: string
  executionId: string
  nodeId: string
}

export class GraphQLClient {
  readonly #graphqlApiUrl: string
  readonly #copilotAuthTokenProvider: CopilotAuthTokenProvider
  readonly #loopsClient: LoopsClient

  constructor(graphqlApiUrl: string, copilotAuthTokenProvider: CopilotAuthTokenProvider, loopsClient: LoopsClient) {
    this.#graphqlApiUrl = graphqlApiUrl
    this.#copilotAuthTokenProvider = copilotAuthTokenProvider
    this.#loopsClient = loopsClient
  }

  /**
   * Executes a GraphQL query against the GitHub API.
   *
   * @param query - The GraphQL query string
   * @param options - Optional configuration object
   * @param options.signal - AbortSignal for request cancellation
   * @param options.nodeExecution - Node execution context for reauth resource handling
   * @returns Promise that resolves to the GraphQL response
   */
  async getGraphQLResponse(query: string, nodeExecution: NodeExecutionContext, options: {signal?: AbortSignal}) {
    // Use loops service for GraphQL execution if feature flag is enabled
    if (isLoopsServiceGraphQLExecutionEnabled()) {
      const result = await this.#loopsClient.executeGraphQL(
        query,
        nodeExecution.loopId,
        nodeExecution.version,
        nodeExecution.executionId,
        nodeExecution.nodeId,
      )

      if (!result.success) {
        throw new Error(`GraphQL execution failed: ${result.error}`)
      }

      if (validateGraphQL(result.data)) {
        return result.data
      }
    }

    const token = await this.#copilotAuthTokenProvider.getAuthToken()

    const headers = {
      ['X-Copilot-Api-Token']: token.value,
    }

    const body: Record<string, string> = {
      query,
    }

    body.loopId = nodeExecution.loopId
    body.version = nodeExecution.version
    body.executionId = nodeExecution.executionId
    body.nodeId = nodeExecution.nodeId

    const response = await reactFetchJSON(this.#graphqlApiUrl, {
      method: 'POST',
      body,
      headers,
      signal: options?.signal,
    })

    if (response.ok) {
      const responseJson = await response.json()
      const requestId = response.headers.get('X-Github-Request-Id') || ''
      if (validateGraphQL(responseJson, requestId)) {
        return responseJson
      }
    } else {
      throw new Error('Failed to get GraphQL response.')
    }
  }
}
