import {Button, FormControl, LabelGroup, Textarea, Token} from '@primer/react'
import {SkeletonText} from '@primer/react/experimental'
import {clsx} from 'clsx'
import React, {useCallback, useMemo, useState} from 'react'

import styles from './PlanningQuestionsForm.module.css'
import type {PlanningQuestions} from './types'

export interface PlanningQuestionsFormProps {
  questions: PlanningQuestions
  isStreaming?: boolean
  isReadOnly?: boolean
  onSubmitAnswers: (message: string) => void
  className?: string
}

export function PlanningQuestionsForm({
  questions,
  isStreaming = false,
  isReadOnly = false,
  onSubmitAnswers,
  className,
}: PlanningQuestionsFormProps) {
  const defaultAnswersFromFirstSuggestions = useMemo(() => {
    const initialAnswers: Record<number, string> = {}
    const initialSelectedSuggestions: Record<number, number> = {}

    for (const [index, q] of questions.questions.entries()) {
      if (!q.suggestions || q.suggestions.length === 0) continue

      const firstSuggestion = q.suggestions[0]!
      initialAnswers[index] = firstSuggestion
      initialSelectedSuggestions[index] = 0
    }

    return {initialAnswers, initialSelectedSuggestions}
  }, [questions.questions])

  const [answers, setAnswers] = useState<Record<number, string>>(defaultAnswersFromFirstSuggestions.initialAnswers)
  const [selectedSuggestions, setSelectedSuggestions] = useState<Record<number, number>>(
    defaultAnswersFromFirstSuggestions.initialSelectedSuggestions,
  )
  const [additionalComments, setAdditionalComments] = useState('')

  const handleAnswerChange = useCallback((questionIndex: number, value: string) => {
    setSelectedSuggestions(prev => {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const {[questionIndex]: _, ...rest} = prev
      return rest
    })
    setAnswers(prev => ({...prev, [questionIndex]: value}))
  }, [])

  const handleSuggestionClick = useCallback(
    (questionIndex: number, suggestionIndex: number, suggestionText: string) => {
      setSelectedSuggestions(prev => ({...prev, [questionIndex]: suggestionIndex}))
      setAnswers(prev => ({...prev, [questionIndex]: suggestionText}))
    },
    [],
  )

  const hasAnswers = useMemo(() => {
    return questions.questions.some((_, index) => answers[index]?.trim()) || additionalComments.trim()
  }, [answers, questions.questions, additionalComments])

  const handleSubmit = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault()

      const parts = []

      for (const [index, q] of questions.questions.entries()) {
        const answer = answers[index]?.trim()
        if (!answer) continue

        parts.push(`Question: ${q.question.trim()}\nAnswer: ${answer}`)
      }

      const additionalCommentsTrimmed = additionalComments.trim()
      if (additionalCommentsTrimmed) {
        parts.push(`Additional comments: ${additionalCommentsTrimmed}`)
      }

      if (parts.length === 0) return
      onSubmitAnswers(parts.join('\n\n'))
    },
    [answers, questions.questions, additionalComments, onSubmitAnswers],
  )

  if (isReadOnly) {
    if (questions.questions.length > 0) {
      return (
        <div>
          <p>Open questions:</p>
          <ul style={{listStyleType: 'none'}}>
            {questions.questions.map(q => (
              <li key={q.question}>{q.question}</li>
            ))}
          </ul>
        </div>
      )
    }

    return null
  }

  if (isStreaming) {
    return (
      <div className={clsx(styles.container, className)}>
        {/* Header */}
        <div className={styles.headerContainer}>
          <div className={styles.headerSection}>
            {/* eslint-disable-next-line primer-react/no-system-props */}
            <SkeletonText maxWidth="50%" size="titleLarge" />

            {/* Outline Section */}
            <div className={styles.outlineSection}>
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="10%" size="subtitle" />
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="25%" />
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="25%" />
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="25%" />
            </div>
          </div>
        </div>

        {/* Questions Section */}
        <div className="pl-3 pt-3 width-full">
          {/* eslint-disable-next-line primer-react/no-system-props */}
          <SkeletonText maxWidth="10%" size="subtitle" />

          {[1, 2, 3].map(num => (
            <div className={styles.questionContainer} key={num}>
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="80%" size="subtitle" />
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="70%" size="bodyLarge" />
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText maxWidth="50%" size="bodySmall" />
            </div>
          ))}
        </div>

        {/* Footer */}
        <div className={styles.footerContainer}>
          {/* eslint-disable-next-line primer-react/no-system-props */}
          <SkeletonText maxWidth="15%" size="titleLarge" />
          {/* eslint-disable-next-line primer-react/no-system-props */}
          <SkeletonText maxWidth="15%" size="titleLarge" />
        </div>
      </div>
    )
  }

  return (
    <form className={clsx(styles.container, className)} onSubmit={handleSubmit}>
      {/* Header */}
      <div className={styles.headerContainer}>
        <div className={styles.headerSection}>
          <div className={styles.title1}>{questions.name}</div>

          {/* Outline Section */}
          {questions.outline.length > 0 && (
            <div className={styles.outlineSection}>
              <div className={styles.title2}>Outline</div>
              <ul className={styles.outlineList}>
                {questions.outline.map(item => (
                  <li key={item}>{item}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </div>

      {/* Questions Section */}
      {questions.questions.length > 0 && (
        <>
          <div className="pt-3">
            <div className={styles.title2}>Open questions</div>
          </div>

          {questions.questions.map(q => {
            const questionIndex = questions.questions.indexOf(q)
            const suggestions = q.suggestions || []
            return (
              <div className={styles.questionContainer} key={q.question}>
                <FormControl className="flex-self-stretch">
                  <FormControl.Label>{q.question}</FormControl.Label>
                  <Textarea
                    block
                    onChange={e => handleAnswerChange(questionIndex, e.target.value)}
                    rows={1}
                    value={answers[questionIndex] || ''}
                  />

                  {suggestions.length > 0 && (
                    <FormControl.Caption className={styles.suggestionsContainer}>
                      Suggestions
                      <LabelGroup className={styles.suggestions}>
                        {suggestions.map(suggestion => {
                          const suggestionIndex = suggestions.indexOf(suggestion)
                          const isSelected = selectedSuggestions[questionIndex] === suggestionIndex

                          return (
                            <Token
                              as="button"
                              isSelected={isSelected}
                              key={suggestion}
                              onClick={() => handleSuggestionClick(questionIndex, suggestionIndex, suggestion)}
                              text={suggestion}
                              type="button"
                            />
                          )
                        })}
                      </LabelGroup>
                    </FormControl.Caption>
                  )}
                </FormControl>
              </div>
            )
          })}
        </>
      )}

      <FormControl className="flex-self-stretch">
        <FormControl.Label>Additional comments</FormControl.Label>
        <Textarea block onChange={e => setAdditionalComments(e.target.value)} rows={3} value={additionalComments} />
      </FormControl>

      {/* Footer */}
      <div className={styles.footerContainer}>
        <Button type="submit" variant="primary" disabled={!hasAnswers}>
          Submit
        </Button>
      </div>
    </form>
  )
}

try{ PlanningQuestionsForm.displayName ||= 'PlanningQuestionsForm' } catch {}