import {useState, useMemo} from 'react'
import {Dialog, Button, FormControl, Textarea, Flash} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useNavigate} from '@github-ui/react-router'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {COPILOT_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {validateLoop} from '../service/validate-loop'
import {useLoopsService} from '../contexts/LoopsServiceProvider'
import {useAppContext} from '../contexts/AppContextProvider'
import type {Loop} from '../types/app'
import styles from './CreateLoopFromJsonDialog.module.css'

interface CreateLoopFromJsonDialogProps {
  isOpen: boolean
  onClose: () => void
}

interface ValidationResult {
  isValid: boolean
  errors: string[]
  loop?: Loop
}

export function CreateLoopFromJsonDialog({isOpen, onClose}: CreateLoopFromJsonDialogProps) {
  const [jsonInput, setJsonInput] = useState('')
  const [isCreating, setIsCreating] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const loopsService = useLoopsService()
  const navigate = useNavigate()
  const {availableModels} = useAppContext()

  const validationResult = useMemo((): ValidationResult => {
    if (!jsonInput.trim()) {
      return {isValid: false, errors: []}
    }

    try {
      const parsed = JSON.parse(jsonInput)
      const validationErrors = validateLoop(parsed, {availableModels})
      if (validationErrors.length > 0) {
        return {
          isValid: false,
          errors: validationErrors.map(err => err.error),
        }
      }

      return {
        isValid: true,
        errors: [],
        loop: parsed,
      }
    } catch (error) {
      return {
        isValid: false,
        errors: [`Invalid JSON: ${error instanceof Error ? error.message : 'Syntax error'}`],
      }
    }
  }, [jsonInput, availableModels])

  const handleCreateLoop = async () => {
    if (!validationResult.isValid || !validationResult.loop || isCreating) return

    setIsCreating(true)
    setCreateError(null)
    sendEvent('dotcom_chat.activate', {target: 'CREATE_LOOP_FROM_JSON', mode: 'loops'})

    try {
      const loopToCreate: Loop = {
        ...validationResult.loop,
        id: crypto.randomUUID(), // Always generate a new ID
        updatedAt: Date.now(),
        owned: true,
        visibility: 'private',
      }

      await loopsService.createLoop(loopToCreate)
      navigate(`${COPILOT_PATH}/l/${loopToCreate.id}`)
      onClose()
    } catch (error) {
      setCreateError(error instanceof Error ? error.message : 'Failed to create loop. Please try again.')
    } finally {
      setIsCreating(false)
    }
  }

  if (!isOpen) return null

  return (
    <Dialog
      title="Create loop from JSON"
      onClose={onClose}
      width="large"
      height="large"
      renderBody={() => (
        <div className={styles.container}>
          {createError && <Flash variant="danger">{createError}</Flash>}
          <div className={styles.header}>
            <p className={styles.description}>Paste a valid loop JSON object to create a new loop.</p>
          </div>

          <FormControl className={styles.formControl}>
            <FormControl.Label visuallyHidden>Loop JSON</FormControl.Label>
            <Textarea
              className={styles.textarea}
              value={jsonInput}
              onChange={e => setJsonInput(e.target.value)}
              placeholder="Paste your loop JSON here..."
              resize="none"
              spellCheck={false}
              autoComplete="off"
            />
            {validationResult.errors.length > 0 ? (
              <FormControl.Validation variant="error">
                <div>{validationResult.errors[0]}</div>
              </FormControl.Validation>
            ) : validationResult.isValid && validationResult.loop ? (
              <FormControl.Validation variant="success">Valid loop detected!</FormControl.Validation>
            ) : (
              // hack to keep consistent spacing when validation message is not shown
              <span className={styles.spacer} />
            )}
          </FormControl>
        </div>
      )}
      renderFooter={() => (
        <Dialog.Footer>
          <Button onClick={onClose}>Cancel</Button>
          <Button
            onClick={handleCreateLoop}
            variant="primary"
            inactive={!validationResult.isValid || isCreating}
            loading={isCreating}
          >
            Create loop
          </Button>
        </Dialog.Footer>
      )}
    />
  )
}

try{ CreateLoopFromJsonDialog.displayName ||= 'CreateLoopFromJsonDialog' } catch {}