import {defaultVersion} from '../utils/versions'

export const VIEW_TYPES = {
  CANVAS: 'canvas',
  OUTPUT: 'output',
} as const

export const SIDE_PANEL_VIEW_TYPES = {
  CHAT: 'chat',
  NODE: 'node',
  ABOUT: 'about',
} as const

export type ViewType = (typeof VIEW_TYPES)[keyof typeof VIEW_TYPES]
export type SidePanelViewType = (typeof SIDE_PANEL_VIEW_TYPES)[keyof typeof SIDE_PANEL_VIEW_TYPES]

export interface LoopsState {
  focusedNodeId: string | null
  hoveredNodeId: string | null
  view: ViewType
  sidePanelView: SidePanelViewType
  version: string
  showLinkCopiedBanner: boolean
  showDuplicatedBanner: boolean
}

export const defaultLoopsState: LoopsState = {
  focusedNodeId: null,
  hoveredNodeId: null,
  view: VIEW_TYPES.CANVAS,
  sidePanelView: SIDE_PANEL_VIEW_TYPES.CHAT,
  version: defaultVersion,
  showLinkCopiedBanner: false,
  showDuplicatedBanner: false,
}
