export interface Loop {
  id: string
  version?: string
  title: string
  description?: string
  nodes: Node[]
  updatedAt: number
  owned: boolean
  visibility: Visibility
  ownerLogin?: string
}

export type NodeValue = string | number | boolean | string[] | object | null

export type Visibility = 'public' | 'private'

type NodeBase = {
  id: string
  title: string
  description: string
  content: string
}

export type RangeInputMetadata = {
  inputType: 'range'
  min: number
  max: number
}

export type TextInputMetadata = {
  inputType: 'text'
}

export type BooleanInputMetadata = {
  inputType: 'boolean'
}

export type SelectInputMetadata = {
  inputType: 'select'
  options: string[]
}

export type DateInputMetadata = {
  inputType: 'date'
}

export type TextNodeMetadata =
  | RangeInputMetadata
  | TextInputMetadata
  | BooleanInputMetadata
  | SelectInputMetadata
  | DateInputMetadata

export type TextNode = NodeBase & {
  type: 'text'
  metadata: TextNodeMetadata
}

export interface PromptNodeMetadata {
  model?: string
}

export type PromptNode = NodeBase & {
  metadata?: {model?: string}
  type: 'prompt'
}

export type CodeNode = NodeBase & {
  type: 'code'
}

export type VisualizeNode = NodeBase & {
  type: 'visualize'
}

export type GitHubGraphQLNode = NodeBase & {
  type: 'github-graphql'
}

export type LoopNode = NodeBase & {
  type: 'loop'
  loopId: string
  loopInputValues?: LoopInputValue[]
}

export type Node = TextNode | PromptNode | CodeNode | VisualizeNode | GitHubGraphQLNode | LoopNode

export type NodeType = Node['type']

export type LoopInputValue = {
  nodeId: string
  inputId: string
  doMapInput?: boolean
}

interface Edge {
  from: string
  to: string
}

export type VirtualNode = {id: string; type: 'output'}

export type GraphNode = Node | VirtualNode

export type LoopGraph<T = Node> = {
  nodes: Map<string, T>
  edges: Edge[]
  layers: T[][]
}

export type CanvasGraph = LoopGraph<GraphNode>

export type ChatMessage = {
  role: 'user' | 'system'
  content: string
}

export interface TokenUsage {
  prompt_tokens: number
  completion_tokens: number
  total_tokens: number
  model: string
}

export const loopErrorType = {
  MissingProperty: 'MissingProperty',
  CycleDetected: 'CycleDetected',
  NonexistentNode: 'NonexistentNode',
  DisconnectedNode: 'DisconnectedNode',
  InvalidBooleanValue: 'InvalidBooleanValue',
  InvalidRangeValue: 'InvalidRangeValue',
  InvalidSelectValue: 'InvalidSelectValue',
  InvalidFileType: 'InvalidFileType',
  EmptyInputValue: 'EmptyInputValue',
  InvalidDateValue: 'InvalidDateValue',
  UnavailableModel: 'UnavailableModel',
} as const

export type LoopErrorType = keyof typeof loopErrorType

export interface LoopValidationError {
  error: string
  errorType: LoopErrorType
  involvedNodes: string[]
}
