import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {VersionName} from '@github-ui/copilot-chat/components/VersionName'
import {disableStreamingFadeIn} from '@github-ui/copilot-markdown'
import {CheckIcon, GitPullRequestIcon, TasklistIcon} from '@primer/octicons-react'
import {ActionList, Spinner} from '@primer/react'

import {
  getRevisionNumber,
  type PlanningTask as VersionedPlanningTask,
} from '../../components/ContentPreview/content-preview-types'
import {useContentPreview} from '../../components/ContentPreview/ContentPreviewContext'
import {usePlanningTaskPullRequest} from '../../components/ContentPreview/planning-task-preview/utils/agent-session'

interface TasklistItemProps {
  isStreaming: boolean
  onClick: (event: React.KeyboardEvent<HTMLElement> | React.MouseEvent<HTMLElement>) => void
  task: VersionedPlanningTask
}

export function TasklistItem({isStreaming, onClick, task}: TasklistItemProps) {
  return (
    // Used by `useCAPIQuery` within `usePlanningTaskPullRequests` for tracking authentication failures in CAPI requests.
    <ConsecutiveCAPI401sProvider>
      <TasklistItemImpl isStreaming={isStreaming} onClick={onClick} task={task} />
    </ConsecutiveCAPI401sProvider>
  )
}

function TasklistItemImpl({isStreaming, onClick, task}: TasklistItemProps) {
  const {pullRequest, isLoading: isPullRequestDataLoading} = usePlanningTaskPullRequest(task)
  const {versionedItems} = useContentPreview()
  const version = getRevisionNumber(task.id, versionedItems)

  const getIcon = () => {
    if (isStreaming || isPullRequestDataLoading) {
      return <Spinner size="small" className={disableStreamingFadeIn} />
    }

    if (pullRequest?.state === 'merged') {
      return <CheckIcon />
    }

    if (pullRequest) {
      return <GitPullRequestIcon />
    }

    return <TasklistIcon />
  }

  return (
    <ActionList.Item key={task.id} onSelect={onClick}>
      <ActionList.LeadingVisual>{getIcon()}</ActionList.LeadingVisual>
      {task.name}
      <ActionList.TrailingVisual>{version != null && <VersionName version={version} />}</ActionList.TrailingVisual>
    </ActionList.Item>
  )
}

try{ TasklistItem.displayName ||= 'TasklistItem' } catch {}
try{ TasklistItemImpl.displayName ||= 'TasklistItemImpl' } catch {}