import {AgentSelector} from '@github-ui/agent-sessions/components/new-task-chat-input/AgentSelector'
import type {DropdownRepository} from '@github-ui/agent-sessions/hooks/useCopilotRepoFetching'
import type {SelectedAgent} from '@github-ui/agent-sessions/types/session'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {RepositoryPicker, type RepositoryPickerRepository} from '@github-ui/item-picker/RepositoryPicker'
import {RefSelector} from '@github-ui/ref-selector'
import {Dialog, FormControl, SkeletonBox} from '@primer/react'
import {useCallback, useEffect, useState} from 'react'

import {PlanningSpecBlockDisplay} from '../../../markdown-extensions/planning-blocks/spec/PlanningSpecBlock'
import type {VersionedPreviewableContentBase} from '../content-preview-types'
import styles from './StartTaskDialog.module.css'
import {useRepositoryDefaultBranch} from './use-repository-default-branch'

const toDropdownRepository = (repo: RepositoryPickerRepository, defaultBranch: string): DropdownRepository => {
  return {
    id: repo.databaseId || 0,
    graphQLId: repo.id,
    name: repo.nameWithOwner,
    nameWithOwner: repo.nameWithOwner,
    nameOnly: repo.name,
    owner: repo.owner.login,
    private: repo.isPrivate || false,
    defaultBranch: defaultBranch || '',
    isEmpty: false,
    enabled: true,
  }
}

interface StartTaskDialogProps {
  previewItem: VersionedPreviewableContentBase
  initialRepo: RepositoryPickerRepository | null | undefined
  topRepos: RepositoryPickerRepository[]
  onStart: (selectedRepo: RepositoryPickerRepository, selectedBranch: string, selectedAgent: SelectedAgent) => void
  onCancel: () => void
}

// TODO - Future notes
// I did not opt for using NewAgentTaskForm since it would require changes on shared form to match our design.
// However, if we are to resume the feature work, we should consider go ahead and adopt the shared form.
export function StartTaskDialog({previewItem, initialRepo, topRepos, onStart, onCancel}: StartTaskDialogProps) {
  const [selectedRepo, setSelectedRepo] = useState<RepositoryPickerRepository | null | undefined>(initialRepo)
  const [repoDefaultBranch, setRepoDefaultBranch] = useState<string>('')
  const [selectedBranch, setSelectedBranch] = useState<string>('')
  const [selectedAgent, setSelectedAgent] = useState<SelectedAgent>({})

  const isSweSubagentsEnabled = isFeatureEnabled('copilot_swe_agent_use_subagents')
  const showSubagentPicker = isSweSubagentsEnabled && selectedBranch

  const {data: defaultBranch, isLoading: isLoadingDefaultBranch} = useRepositoryDefaultBranch(
    selectedRepo?.owner?.login,
    selectedRepo?.name,
  )

  useEffect(() => {
    if (defaultBranch != null) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setRepoDefaultBranch(defaultBranch)
      setSelectedBranch(defaultBranch)
    } else {
      setRepoDefaultBranch('')
    }
  }, [defaultBranch])

  const onBranchSelect = useCallback((ref: string) => {
    setSelectedBranch(ref)
  }, [])

  const onRepoSelect = useCallback((newSelectedRepo: RepositoryPickerRepository | undefined) => {
    setSelectedRepo(newSelectedRepo)
  }, [])

  // Handle start task
  const handleStart = useCallback(() => {
    onStart(selectedRepo!, selectedBranch, selectedAgent)
  }, [onStart, selectedRepo, selectedBranch, selectedAgent])

  const isLoading = isLoadingDefaultBranch
  const canSubmit = !!selectedRepo && !!selectedBranch

  return (
    <Dialog
      width="xlarge"
      title="Start task"
      onClose={onCancel}
      footerButtons={[
        {
          buttonType: 'default',
          content: 'Cancel',
          onClick: onCancel,
        },
        {
          buttonType: 'primary',
          content: 'Start',
          onClick: handleStart,
          disabled: !canSubmit,
        },
      ]}
    >
      <div className={styles.formContainer}>
        <div className={styles.selectorsRow}>
          <FormControl>
            <FormControl.Label>Target repository</FormControl.Label>
            <RepositoryPicker
              initialRepository={selectedRepo || undefined}
              onSelect={onRepoSelect}
              topRepositories={topRepos}
              enforceAtleastOneSelected
              options={{includeForks: true}}
              preventDefault
              responsiveOnNarrow
            />
          </FormControl>

          <FormControl>
            <FormControl.Label>Base branch</FormControl.Label>
            {selectedRepo || selectedBranch ? (
              <RefSelector
                useFocusZone
                cacheKey="brainstorm-start-task-ref-selector"
                canCreate={false}
                currentCommitish={!repoDefaultBranch ? 'None available' : selectedBranch}
                defaultBranch={repoDefaultBranch}
                owner={selectedRepo?.owner?.login || ''}
                repo={selectedRepo?.name || ''}
                types={['branch']}
                selectedRefType="branch"
                closeOnSelect
                hideShowAll
                disabled={isLoading}
                onSelectItem={onBranchSelect}
                anchoredOverlayProps={{
                  variant: {regular: 'anchored', narrow: 'fullscreen'},
                  height: 'small',
                }}
              />
            ) : (
              <SkeletonBox height="32px" width="100px" />
            )}
          </FormControl>

          {showSubagentPicker && selectedRepo && (
            <FormControl>
              <FormControl.Label>Custom agent</FormControl.Label>
              <AgentSelector
                repo={toDropdownRepository(selectedRepo, repoDefaultBranch)}
                branch={selectedBranch}
                selectedAgent={selectedAgent}
                onSelectAgent={agent => setSelectedAgent(agent)}
                iconOnly={false}
                disabled={isLoading}
              />
            </FormControl>
          )}
        </div>

        <div className={styles.taskContainer}>
          <FormControl>
            <FormControl.Label>Task</FormControl.Label>
            <PlanningSpecBlockDisplay previewItem={previewItem} />
          </FormControl>
        </div>
      </div>
    </Dialog>
  )
}

try{ StartTaskDialog.displayName ||= 'StartTaskDialog' } catch {}