import {createContext, useContext} from 'react'
import type {LoopsService} from '../service/loops-service'

const LoopsServiceContext = createContext<LoopsService | null>(null)

export const LoopsServiceProvider = LoopsServiceContext.Provider

export function useLoopsService(): LoopsService {
  const s = useContext(LoopsServiceContext)
  if (!s) throw new Error('useLoopsService must be used inside a LoopsServiceProvider')
  return s
}

export function useOptionalLoopsService(): LoopsService | null {
  return useContext(LoopsServiceContext)
}

try{ LoopsServiceContext.displayName ||= 'LoopsServiceContext' } catch {}