import {Banner} from '@primer/react'
import {useEffect, useState} from 'react'

interface TaskErrorBannerProps {
  error: {message: string}
  onDismiss: () => void
}

export function TaskErrorBanner({error, onDismiss}: TaskErrorBannerProps) {
  const [bannerKey, setBannerKey] = useState(0)

  useEffect(() => {
    // Reset banner key to trigger re-render and accessibility announcements
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setBannerKey(prev => prev + 1)
  }, [error])

  return (
    <Banner
      key={bannerKey}
      aria-atomic="true"
      role="alert"
      variant="critical"
      title="Failed to start task"
      hideTitle
      description={error.message}
      onDismiss={onDismiss}
    />
  )
}

try{ TaskErrorBanner.displayName ||= 'TaskErrorBanner' } catch {}