// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {ImmersivePlugin} from '@github-ui/copilot-chat/plugin'
import {LoopsService} from '../service/loops-service'
import {LOOPS_PLUGIN_ID} from './constants'

export function isLoopsPlugin(
  plugin: ImmersivePlugin,
): plugin is ImmersivePlugin & {service: LoopsService; previewUrl: string} {
  return plugin.id === LOOPS_PLUGIN_ID && 'service' in plugin && plugin.service instanceof LoopsService
}
