import {useQuery} from '@github-ui/react-query'
import {useParams, useSearchParams} from '@github-ui/react-router'
import type {AgentTaskAppPayload} from '../types/agent-task-app-payload'
import {useAppPayload} from '@github-ui/react-core/use-app-payload'

async function fetchAppPayload(globalID: string | undefined, sessionId: string | null): Promise<AgentTaskAppPayload> {
  if (!globalID) {
    throw new Error('No globalID provided')
  }
  const url = new URL(`/copilot/tasks/pull/${globalID}`, window.location.origin)

  // If we have a session ID, include it in case the user doesn't have access to the entire task
  if (sessionId) {
    url.searchParams.set('session_id', sessionId)
  }
  const response = await fetch(url.toString(), {
    headers: {
      Accept: 'application/json',
      'X-Requested-With': 'XMLHttpRequest',
    },
  })

  if (!response.ok) {
    throw new Error(`Failed to fetch task payload for ${globalID}`)
  }

  const data = await response.json()
  return data
}

function hasExpectedKeys<T extends Record<string, unknown>>(data: unknown, keys: Array<keyof T>): data is T {
  return typeof data === 'object' && data !== null && keys.every(key => key in data)
}

const agentTaskKeys: Array<keyof AgentTaskAppPayload> = [
  'pull',
  'sessions',
  'currentUser',
  'currentUserCanPush',
  'steeringEnabled',
  'logsPollingInterval',
  'sessionsPollingInterval',
]

function isTaskAppPayload(payload: unknown): payload is AgentTaskAppPayload {
  return !!payload && hasExpectedKeys<AgentTaskAppPayload>(payload, agentTaskKeys)
}

export function useOrFetchTaskViewPayload(): ReturnType<typeof useQuery<AgentTaskAppPayload>> {
  const ssrPayload = useAppPayload<AgentTaskAppPayload>()
  const {globalID} = useParams<{globalID?: string}>()
  const [searchParams] = useSearchParams()
  const sessionId = searchParams.get('session_id')
  const payloadIsValid =
    isTaskAppPayload(ssrPayload) && globalID && ssrPayload.pull && ssrPayload.pull.global_relay_id === globalID
  const validPayload = payloadIsValid ? ssrPayload : undefined

  const queryResponse = useQuery<AgentTaskAppPayload>({
    queryKey: ['agent-task-payload', globalID, sessionId],
    queryFn: () => fetchAppPayload(globalID, sessionId),
    initialData: validPayload,
    enabled: !!globalID && !validPayload,
    staleTime: Infinity,
  })

  return queryResponse
}
